                          </AnimatePresence>
                        </motion.div>
                      );
                    })}
                  </div>
                )}
              </motion.div>
            )}

            {/* --- TAB 3: MANUAL LEDGER JOURNAL ENTRY --- */}
            {activeTab === 'MANUAL_JOURNAL' && (
              <motion.div 
                key="manual_journal"
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -10 }}
