'use client';

import { useState, useMemo, useEffect } from 'react';
import { toast } from 'sonner';
import { Factory, X, Plus, Trash2, Sparkles, Scale, RefreshCw, CheckCircle2, AlertCircle, Calculator, Zap, ChevronRight, ArrowLeft } from 'lucide-react';
import { convertPaddyToRiceAction } from '@/app/actions/inventory';
import { motion, AnimatePresence } from 'framer-motion';

interface MilledOutputRow {
  id: string;
  outputType: string;
  bagCapacityKg: string;
  numberOfBags: string;
}

interface MillingConversionModalProps {
  isOpen: boolean;
  onClose: () => void;
  godowns: Array<{ id: string; name: string }>;
  paddyProducts: Array<{ id: string; name: string }>;
  lots: Array<{ id: string; productId: string; godownId: string; currentQuantity: number | string }>;
  initialGodownId?: string;
  initialProductId?: string;
}

const OUTPUT_TYPES = [
  'Fine Rice',
  'Broken Rice',
  'Black Rice',
  'Mixed Rice',
  'Bran',
  'Husk',
  'Raw Rice'
];

const CAPACITY_PRESETS = ['25', '50', '75'];

export default function MillingConversionModal({
  isOpen,
  onClose,
  godowns,
  paddyProducts,
  lots,
  initialGodownId = '',
  initialProductId = ''
}: MillingConversionModalProps) {
  const [sourceGodownId, setSourceGodownId] = useState(initialGodownId);
  const [productId, setProductId] = useState(initialProductId);

  // Wizard Step: 1 = Source Selection, 2 = Output Bags & Confirm
  const [currentStep, setCurrentStep] = useState<1 | 2>(1);

  // Dynamic Milled Output Rows
  const [outputRows, setOutputRows] = useState<MilledOutputRow[]>([
    { id: '1', outputType: 'Fine Rice', bagCapacityKg: '50', numberOfBags: '100' },
    { id: '2', outputType: 'Broken Rice', bagCapacityKg: '50', numberOfBags: '20' },
    { id: '3', outputType: 'Bran', bagCapacityKg: '50', numberOfBags: '10' }
  ]);

  // Optional Moisture / Invisible Loss (KG)
  const [moistureLossKg, setMoistureLossKg] = useState('0');

  const [isSubmitting, setIsSubmitting] = useState(false);

  // 1. PERSISTENT PADDY GODOWNS: Include all Paddy Godowns
  const paddyGodowns = useMemo(() => {
    return godowns.filter(g => {
      const name = g.name.toLowerCase();
      return !name.includes('rice') && !name.includes('packaging');
    });
  }, [godowns]);

  // Sync initial props when modal opens
  useEffect(() => {
    if (isOpen) {
      if (initialGodownId) {
        setSourceGodownId(initialGodownId);
      } else if (paddyGodowns.length > 0) {
        setSourceGodownId(paddyGodowns[0].id);
      }
      if (initialProductId) {
        setProductId(initialProductId);
      }
      setCurrentStep(1);
    }
  }, [isOpen, initialGodownId, initialProductId, paddyGodowns]);

  // 2. DYNAMIC PADDY VARIETY DROPDOWN
  const availableVarietiesInGodown = useMemo(() => {
    if (!sourceGodownId) return paddyProducts;

    const activeProductIds = Array.from(new Set(
      lots
        .filter(l => l.godownId === sourceGodownId && Number(l.currentQuantity) > 0)
        .map(l => l.productId)
    ));

    const godownProducts = paddyProducts.filter(p => activeProductIds.includes(p.id));
    return godownProducts.length > 0 ? godownProducts : paddyProducts;
  }, [sourceGodownId, lots, paddyProducts]);

  // Auto-select variety
  useEffect(() => {
    if (availableVarietiesInGodown.length > 0) {
      if (!productId || !availableVarietiesInGodown.some(p => p.id === productId)) {
        setProductId(availableVarietiesInGodown[0].id);
      }
    }
  }, [availableVarietiesInGodown, productId]);

  // 3. AVAILABLE STOCK IN GODOWN & VARIETY
  const maxAvailableStock = useMemo(() => {
    if (!sourceGodownId || !productId) return 0;
    return lots
      .filter(l => l.godownId === sourceGodownId && l.productId === productId)
      .reduce((sum, l) => sum + Number(l.currentQuantity), 0);
  }, [sourceGodownId, productId, lots]);

  // Row management
  const addOutputRow = () => {
    setOutputRows([
      ...outputRows,
      { id: Date.now().toString(), outputType: 'Fine Rice', bagCapacityKg: '50', numberOfBags: '' }
    ]);
  };

  const removeOutputRow = (id: string) => {
    if (outputRows.length === 1) {
      toast.error('At least one output row is required.');
      return;
    }
    setOutputRows(outputRows.filter(r => r.id !== id));
  };

  const updateOutputRow = (id: string, field: keyof MilledOutputRow, value: string) => {
    setOutputRows(outputRows.map(r => r.id === id ? { ...r, [field]: value } : r));
  };

  const adjustBagsForRow = (id: string, delta: number) => {
    setOutputRows(outputRows.map(r => {
      if (r.id !== id) return r;
      const current = parseFloat(r.numberOfBags) || 0;
      const updated = Math.max(0, current + delta);
      return { ...r, numberOfBags: updated.toString() };
    }));
  };

  // 1-TAP TEMPLATE PRESETS (ZERO TYPING REQUIRED!)
  const applyPresetTemplate = (preset: 'standard' | 'large' | 'clear') => {
    if (preset === 'standard') {
      setOutputRows([
        { id: '1', outputType: 'Fine Rice', bagCapacityKg: '50', numberOfBags: '100' },
        { id: '2', outputType: 'Broken Rice', bagCapacityKg: '50', numberOfBags: '20' },
        { id: '3', outputType: 'Bran', bagCapacityKg: '50', numberOfBags: '10' }
      ]);
      toast.success('Loaded 100 bags Fine + 20 bags Broken + 10 bags Bran template!');
    } else if (preset === 'large') {
      setOutputRows([
        { id: '1', outputType: 'Fine Rice', bagCapacityKg: '50', numberOfBags: '200' },
        { id: '2', outputType: 'Broken Rice', bagCapacityKg: '50', numberOfBags: '40' },
        { id: '3', outputType: 'Bran', bagCapacityKg: '50', numberOfBags: '20' }
      ]);
      toast.success('Loaded 200 bags Fine + 40 bags Broken + 20 bags Bran template!');
    } else if (preset === 'clear') {
      setOutputRows([
        { id: '1', outputType: 'Fine Rice', bagCapacityKg: '50', numberOfBags: '' }
      ]);
      toast('Reset all output rows.');
    }
  };

  // REVERSE CALCULATION: Total Milled Outputs + Moisture Loss = Total Paddy Consumed
  const totalMilledOutputsKg = useMemo(() => {
    return outputRows.reduce((sum, row) => {
      const cap = parseFloat(row.bagCapacityKg) || 0;
      const bags = parseFloat(row.numberOfBags) || 0;
      return sum + (cap * bags);
    }, 0);
  }, [outputRows]);

  const lossKg = parseFloat(moistureLossKg) || 0;
  const totalPaddyConsumedKg = totalMilledOutputsKg + lossKg;

  // Validation: Calculated consumption vs Available Stock
  const isConsumptionExceeded = totalPaddyConsumedKg > maxAvailableStock;

  // Submit Handler
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!sourceGodownId) return toast.error('Please select a Source Paddy Godown.');
    if (!productId) return toast.error('Please select a Paddy Variety.');
    if (totalPaddyConsumedKg <= 0) {
      return toast.error('Please enter No. of Bags for at least one output row.');
    }
    if (isConsumptionExceeded) {
      return toast.error(`Calculated consumption (${totalPaddyConsumedKg.toLocaleString('en-IN')} KG) exceeds available stock (${maxAvailableStock.toLocaleString('en-IN')} KG).`);
    }

    // Process output rows
    const validOutputs = outputRows
      .map(r => ({
        outputType: r.outputType,
        bagCapacityKg: parseFloat(r.bagCapacityKg) || 0,
        numberOfBags: parseFloat(r.numberOfBags) || 0,
        quantityKg: (parseFloat(r.bagCapacityKg) || 0) * (parseFloat(r.numberOfBags) || 0)
      }))
      .filter(o => o.quantityKg > 0);

    setIsSubmitting(true);
    try {
      const formData = new FormData();
      formData.append('sourceGodownId', sourceGodownId);
      formData.append('productId', productId);
      formData.append('paddyQuantityKg', totalPaddyConsumedKg.toString());
      formData.append('moistureLossKg', lossKg.toString());
      formData.append('milledOutputs', JSON.stringify(validOutputs));

      await convertPaddyToRiceAction(formData);
      toast.success('Milling batch processed! Deducted calculated paddy consumption and updated Central Rice Storage Godown.');
      onClose();
    } catch (err: any) {
      toast.error('Milling batch processing failed: ' + (err?.message || String(err)));
    } finally {
      setIsSubmitting(false);
    }
  };

  if (!isOpen) return null;

  return (
    <AnimatePresence>
      <div className="fixed inset-0 z-[300] flex items-end sm:items-center justify-center p-0 sm:p-4">
        {/* Backdrop */}
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          onClick={onClose}
          className="fixed inset-0 bg-black/90 backdrop-blur-md"
        />

        {/* Mobile Full Bottom Drawer Window */}
        <motion.div
          initial={{ y: '100%', opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          exit={{ y: '100%', opacity: 0 }}
          transition={{ type: 'spring', damping: 25, stiffness: 250 }}
          className="relative w-full max-w-2xl bg-[#1A1A1A] border-t-2 sm:border-2 border-[#F5A623] rounded-t-3xl sm:rounded-2xl shadow-2xl overflow-hidden z-10 text-white font-sans h-[94vh] sm:h-auto sm:max-h-[92vh] flex flex-col"
        >
          {/* Mobile Handle */}
          <div className="w-12 h-1.5 bg-neutral-700 rounded-full mx-auto my-2 block sm:hidden shrink-0" />

          {/* Header */}
          <div className="bg-[#121212] p-4 sm:p-5 border-b border-[#F5A623]/30 flex justify-between items-center shrink-0">
            <div className="flex items-center gap-3">
              {currentStep === 2 && (
                <button
                  type="button"
                  onClick={() => setCurrentStep(1)}
                  className="p-2 bg-neutral-900 border border-neutral-800 rounded-xl text-neutral-300 hover:text-white"
                >
                  <ArrowLeft className="w-4 h-4" />
                </button>
              )}
              <div className="w-10 h-10 rounded-xl bg-[#F5A623]/10 border border-[#F5A623] flex items-center justify-center text-[#F5A623] shrink-0">
                <Factory className="w-5 h-5" />
              </div>
              <div>
                <h3 className="font-display font-black text-base sm:text-lg uppercase tracking-wider text-[#F5A623]">
                  Process Milling Batch
                </h3>
                <p className="text-[11px] text-neutral-400">Step {currentStep} of 2 • Reverse-Calculated Yield</p>
              </div>
            </div>
            <button onClick={onClose} className="p-2 text-neutral-400 hover:text-white rounded-xl hover:bg-neutral-800">
              <X className="w-6 h-6" />
            </button>
          </div>

          {/* STEPPER PROGRESS TABS */}
          <div className="flex border-b border-neutral-800 bg-[#121212]">
            <button
              onClick={() => setCurrentStep(1)}
              className={`flex-1 py-2.5 text-xs font-display font-black uppercase tracking-wider text-center transition-colors border-b-2 ${
                currentStep === 1 
                  ? 'border-[#F5A623] text-[#F5A623] bg-[#F5A623]/10' 
                  : 'border-transparent text-neutral-400'
              }`}
            >
              1. Source & Variety
            </button>
            <button
              onClick={() => setCurrentStep(2)}
              className={`flex-1 py-2.5 text-xs font-display font-black uppercase tracking-wider text-center transition-colors border-b-2 ${
                currentStep === 2 
                  ? 'border-[#F5A623] text-[#F5A623] bg-[#F5A623]/10' 
                  : 'border-transparent text-neutral-400'
              }`}
            >
              2. Output Bags ({outputRows.length} Rows)
            </button>
          </div>

          {/* Form Scroll Area */}
          <form onSubmit={handleSubmit} className="p-4 sm:p-6 overflow-y-auto space-y-6 flex-1 pb-28 sm:pb-6">

            {/* ========================================================================= */}
            {/* STEP 1: SOURCE SELECTION */}
            {/* ========================================================================= */}
            {currentStep === 1 && (
              <motion.div initial={{ opacity: 0, x: -10 }} animate={{ opacity: 1, x: 0 }} className="space-y-6">
                <div className="p-5 bg-neutral-900 rounded-2xl border border-[#F5A623]/40 space-y-4 shadow-lg">
                  <div className="flex items-center justify-between border-b border-neutral-800 pb-2.5">
                    <span className="text-xs font-black uppercase tracking-widest text-[#F5A623]">
                      Source Paddy Selection
                    </span>
                    {productId && (
                      <span className="text-xs font-mono font-bold text-[#F5A623]">
                        Stock: {maxAvailableStock.toLocaleString('en-IN')} KG
                      </span>
                    )}
                  </div>

                  <div className="space-y-4">
                    {/* Source Godown */}
                    <div>
                      <label className="text-xs font-bold uppercase tracking-wider text-neutral-400 block mb-1">
                        Source Paddy Godown *
                      </label>
                      <select
                        value={sourceGodownId}
                        onChange={e => setSourceGodownId(e.target.value)}
                        required
                        className="w-full bg-[#121212] border border-[#F5A623]/40 rounded-xl p-3.5 text-sm text-white focus:outline-none focus:border-[#F5A623] min-h-[48px]"
                      >
                        <option value="">Select Paddy Godown...</option>
                        {paddyGodowns.map(g => (
                          <option key={g.id} value={g.id}>{g.name}</option>
                        ))}
                      </select>
                    </div>

                    {/* Paddy Variety */}
                    <div>
                      <label className="text-xs font-bold uppercase tracking-wider text-neutral-400 block mb-1">
                        Paddy Variety *
                      </label>
                      <select
                        value={productId}
                        onChange={e => setProductId(e.target.value)}
                        required
                        disabled={!sourceGodownId}
                        className="w-full bg-[#121212] border border-[#F5A623]/40 rounded-xl p-3.5 text-sm text-white focus:outline-none focus:border-[#F5A623] disabled:opacity-50 min-h-[48px]"
                      >
                        {!sourceGodownId ? (
                          <option value="">Select Godown First...</option>
                        ) : (
                          availableVarietiesInGodown.map(p => (
                            <option key={p.id} value={p.id}>{p.name}</option>
                          ))
                        )}
                      </select>
                    </div>
                  </div>
                </div>

                <button
                  type="button"
                  onClick={() => setCurrentStep(2)}
                  disabled={!sourceGodownId || !productId}
                  className="w-full py-4 bg-[#F5A623] hover:bg-[#d98e19] text-black font-black uppercase tracking-wider rounded-xl shadow-xl transition-all disabled:opacity-50 min-h-[52px] text-sm flex items-center justify-center gap-2"
                >
                  <span>NEXT: ENTER OUTPUT BAGS</span>
                  <ChevronRight className="w-5 h-5" />
                </button>
              </motion.div>
            )}

            {/* ========================================================================= */}
            {/* STEP 2: OUTPUT BAGS & 1-TAP QUICK PRESETS */}
            {/* ========================================================================= */}
            {currentStep === 2 && (
              <motion.div initial={{ opacity: 0, x: 10 }} animate={{ opacity: 1, x: 0 }} className="space-y-6">

                {/* 1-TAP TEMPLATE PRESETS BAR */}
                <div className="p-3 bg-[#121212] rounded-2xl border border-[#F5A623]/40 space-y-2">
                  <span className="text-[10px] font-black uppercase tracking-wider text-[#F5A623] flex items-center gap-1.5">
                    <Zap className="w-3.5 h-3.5 text-[#F5A623]" /> 1-Tap Quick Yield Templates:
                  </span>
                  <div className="flex flex-wrap gap-2">
                    <button
                      type="button"
                      onClick={() => applyPresetTemplate('standard')}
                      className="px-3 py-1.5 bg-[#F5A623]/20 hover:bg-[#F5A623] text-[#F5A623] hover:text-black border border-[#F5A623]/40 rounded-xl font-bold text-xs transition-all"
                    >
                      ⚡ 100 Bags Fine (Standard)
                    </button>

                    <button
                      type="button"
                      onClick={() => applyPresetTemplate('large')}
                      className="px-3 py-1.5 bg-[#F5A623]/20 hover:bg-[#F5A623] text-[#F5A623] hover:text-black border border-[#F5A623]/40 rounded-xl font-bold text-xs transition-all"
                    >
                      ⚡ 200 Bags Fine (Large)
                    </button>

                    <button
                      type="button"
                      onClick={() => applyPresetTemplate('clear')}
                      className="px-3 py-1.5 bg-neutral-800 text-neutral-400 hover:text-white rounded-xl font-bold text-xs"
                    >
                      Reset
                    </button>
                  </div>
                </div>

                {/* Output Rows */}
                <div className="space-y-4">
                  {outputRows.map((row, idx) => {
                    const cap = parseFloat(row.bagCapacityKg) || 0;
                    const bags = parseFloat(row.numberOfBags) || 0;
                    const calculatedYieldKg = cap * bags;

                    return (
                      <div key={row.id} className="p-4 bg-neutral-900 rounded-2xl border border-neutral-800 space-y-3">

                        <div className="flex justify-between items-center border-b border-neutral-800 pb-2">
                          <span className="text-xs font-black uppercase text-[#F5A623] tracking-wider">
                            Output #{idx + 1}: {row.outputType}
                          </span>
                          <button
                            type="button"
                            onClick={() => removeOutputRow(row.id)}
                            className="text-neutral-500 hover:text-red-400 text-xs font-bold uppercase flex items-center gap-1"
                          >
                            <Trash2 className="w-4 h-4" />
                          </button>
                        </div>

                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                          {/* 1. Output Type Select */}
                          <div>
                            <label className="text-[10px] font-bold uppercase tracking-wider text-neutral-400 block mb-1">
                              Output Type *
                            </label>
                            <select
                              value={row.outputType}
                              onChange={e => updateOutputRow(row.id, 'outputType', e.target.value)}
                              className="w-full bg-[#121212] border border-[#F5A623]/30 rounded-xl p-3 text-xs font-bold text-white focus:outline-none focus:border-[#F5A623] min-h-[44px]"
                            >
                              {OUTPUT_TYPES.map(t => (
                                <option key={t} value={t}>{t}</option>
                              ))}
                            </select>
                          </div>

                          {/* 2. Bag Capacity (KG) */}
                          <div>
                            <div className="flex justify-between items-center mb-1">
                              <label className="text-[10px] font-bold uppercase tracking-wider text-neutral-400">
                                Bag Weight (KG) *
                              </label>
                              <div className="flex gap-1">
                                {CAPACITY_PRESETS.map(preset => (
                                  <button
                                    key={preset}
                                    type="button"
                                    onClick={() => updateOutputRow(row.id, 'bagCapacityKg', preset)}
                                    className={`text-[9px] font-mono px-1.5 py-0.5 rounded border transition-colors ${
                                      row.bagCapacityKg === preset 
                                        ? 'bg-[#F5A623] text-black font-black border-[#F5A623]' 
                                        : 'bg-neutral-800 text-neutral-300 border-neutral-700'
                                    }`}
                                  >
                                    {preset}k
                                  </button>
                                ))}
                              </div>
                            </div>
                            <input
                              type="number"
                              step="0.1"
                              value={row.bagCapacityKg}
                              onChange={e => updateOutputRow(row.id, 'bagCapacityKg', e.target.value)}
                              className="w-full bg-[#121212] border border-[#F5A623]/30 rounded-xl p-3 font-mono text-xs text-white focus:outline-none focus:border-[#F5A623] min-h-[44px]"
                            />
                          </div>
                        </div>

                        {/* 3. QUICK INCREMENT CHIPS & NO OF BAGS */}
                        <div>
                          <div className="flex justify-between items-center mb-1.5">
                            <label className="text-[10px] font-bold uppercase tracking-wider text-neutral-400">
                              No. of Bags *
                            </label>
                            {/* 1-TAP QUICK BAG INCREMENT CHIPS */}
                            <div className="flex gap-1">
                              {[10, 50, 100].map(inc => (
                                <button
                                  key={inc}
                                  type="button"
                                  onClick={() => adjustBagsForRow(row.id, inc)}
                                  className="text-[9px] font-mono px-2 py-0.5 bg-[#F5A623]/15 text-[#F5A623] border border-[#F5A623]/30 rounded-lg hover:bg-[#F5A623] hover:text-black font-bold transition-all"
                                >
                                  +{inc}
                                </button>
                              ))}
                            </div>
                          </div>

                          <div className="flex items-center gap-1">
                            <button
                              type="button"
                              onClick={() => adjustBagsForRow(row.id, -10)}
                              className="w-10 h-[46px] bg-neutral-800 text-white font-black rounded-l-xl border border-neutral-700 active:bg-neutral-700 flex items-center justify-center shrink-0 text-base"
                            >
                              -
                            </button>
                            <input
                              type="number"
                              step="1"
                              placeholder="0"
                              value={row.numberOfBags}
                              onChange={e => updateOutputRow(row.id, 'numberOfBags', e.target.value)}
                              className="w-full bg-[#121212] border border-[#F5A623]/40 p-2.5 text-center font-mono font-black text-base text-white focus:outline-none focus:border-[#F5A623] min-h-[46px]"
                            />
                            <button
                              type="button"
                              onClick={() => adjustBagsForRow(row.id, 10)}
                              className="w-10 h-[46px] bg-neutral-800 text-white font-black rounded-r-xl border border-neutral-700 active:bg-neutral-700 flex items-center justify-center shrink-0 text-base"
                            >
                              +
                            </button>
                          </div>
                        </div>

                        {/* Yield Subtotal Badge */}
                        <div className="flex justify-between items-center p-2.5 bg-black/60 rounded-xl border border-neutral-800">
                          <span className="text-[10px] font-bold uppercase tracking-wider text-neutral-400">
                            Output Yield:
                          </span>
                          <span className="font-mono font-black text-xs text-[#F5A623]">
                            {calculatedYieldKg > 0 ? `${calculatedYieldKg.toLocaleString('en-IN')} KG` : '0 KG'}
                          </span>
                        </div>

                      </div>
                    );
                  })}
                </div>

                {/* Add Row Button */}
                <button
                  type="button"
                  onClick={addOutputRow}
                  className="w-full py-3 px-4 bg-neutral-800 hover:bg-neutral-700 text-[#F5A623] font-bold text-xs uppercase tracking-wider rounded-xl border border-[#F5A623]/40 flex items-center justify-center gap-2 transition-colors min-h-[48px]"
                >
                  <Plus className="w-4 h-4" /> [+ Add Another Output Row]
                </button>

                {/* REVERSE CONSUMPTION BANNER */}
                <div className={`p-4 rounded-2xl border-2 transition-all ${
                  isConsumptionExceeded 
                    ? 'bg-red-950/40 border-red-500/80 text-red-200' 
                    : 'bg-[#121212] border-[#F5A623] text-white'
                }`}>
                  <div className="flex justify-between items-center">
                    <div>
                      <span className="text-[10px] font-black uppercase tracking-widest text-neutral-400 block">
                        Auto-Calculated Paddy Input
                      </span>
                      <h4 className="font-display font-black text-sm uppercase tracking-wider">
                        TOTAL PADDY CONSUMED
                      </h4>
                    </div>

                    <div className="text-right">
                      <span className={`font-mono font-black text-2xl block tabular-nums ${
                        isConsumptionExceeded ? 'text-red-400' : 'text-[#F5A623]'
                      }`}>
                        {totalPaddyConsumedKg.toLocaleString('en-IN')} KG
                      </span>
                    </div>
                  </div>

                  {isConsumptionExceeded && (
                    <div className="mt-2 pt-2 border-t border-red-500/40 flex items-center gap-2 text-xs font-bold text-red-400">
                      <AlertCircle className="w-4 h-4 shrink-0" />
                      <span>Exceeds available stock (Max: {maxAvailableStock.toLocaleString('en-IN')} KG).</span>
                    </div>
                  )}
                </div>

              </motion.div>
            )}

          </form>

          {/* Sticky Mobile Footer Submit */}
          {currentStep === 2 && (
            <div className="sticky bottom-0 bg-[#121212] p-4 border-t border-neutral-800 shadow-2xl z-30 shrink-0">
              <button
                type="button"
                onClick={handleSubmit}
                disabled={isSubmitting || isConsumptionExceeded || totalPaddyConsumedKg <= 0}
                className="w-full bg-[#F5A623] hover:bg-[#d98e19] text-black font-black uppercase tracking-wider py-4 rounded-xl shadow-xl transition-all active:scale-[0.99] disabled:opacity-50 min-h-[52px] text-base flex items-center justify-center gap-2"
              >
                {isSubmitting ? (
                  <>
                    <RefreshCw className="w-5 h-5 animate-spin" />
                    <span>PROCESSING MILLING...</span>
                  </>
                ) : (
                  <>
                    <Factory className="w-5 h-5" />
                    <span>[ PROCESS MILLING BATCH ]</span>
                  </>
                )}
              </button>
            </div>
          )}

        </motion.div>
      </div>
    </AnimatePresence>
  );
}

'use client';

import { useState } from 'react';
import { useRouter } from 'next/navigation';
import { toast } from 'sonner';
import { Landmark, ArrowDownCircle, ArrowUpCircle, Truck, Package, UserCheck, Phone, FileText, Wallet, CheckCircle2, Clock, Tags, RefreshCw, X } from 'lucide-react';
import { recordTransactionAction, confirmProcurementPaymentAction, confirmSalesReceiptAction, confirmPackingItemPaymentAction } from '@/app/actions/accounting';
import { Input, Select } from '@/components/ui/Input';
import { Button } from '@/components/ui/Button';
import { Badge } from '@/components/ui/Badge';
import { motion, AnimatePresence } from 'framer-motion';

type Customer = { id: string; name: string; contact?: string | null; gstin?: string | null; address?: string | null; balance: number | string | { toString(): string } };
type Supplier = { id: string; name: string; contact?: string | null; gstin?: string | null; balance: number | string | { toString(): string } };
type ExpenseCategory = { id: string; name: string };
type Bank = { id: string; bankName: string; accountNumber: string; balance: number | string | { toString(): string } };

export type PaymentHistory = { id: string; amount: string; date: string };

export type PendingProcurementBatch = {
  id: string;
  createdAt: string;
  status?: string;
  amountPaid?: string;
  payments?: PaymentHistory[];
  grossWeight: string | number;
  netWeight: string | number | null;
  numberOfBags: string | number | null;
  perBagWeight: string | number | null;
  farmerBagRate: string | number | null;
  farmerTotalPayable: string | number | null;
  brokerCommissionRate: string | number | null;
  brokerCommissionTotal: string | number | null;
  supplier: { id: string; name: string; contact?: string | null; gstin?: string | null };
  farmer?: { id: string; name: string; contact?: string | null; village?: string | null } | null;
  product?: { id: string; name: string } | null;
  godown?: { id: string; name: string } | null;
};

export type PendingPackingItem = {
  id: string;
  brandName: string;
  status?: string;
  amountPaid?: string;
  payments?: PaymentHistory[];
  capacityKg: string | number;
  quantityBags: string | number;
  perBagRate: string | number;
  createdAt: string;
  godown: { id: string; name: string };
  supplier?: { id: string; name: string; contact?: string | null; gstin?: string | null } | null;
};

export type PendingSalesInvoice = {
  id: string;
  invoiceNumber: string;
  createdAt: string;
  status?: string;
  amountPaid?: string;
  payments?: PaymentHistory[];
  subtotal: string | number;
  taxTotal: string | number;
  grandTotal: string | number;
  customer: { id: string; name: string; contact?: string | null; gstin?: string | null; address?: string | null; balance: string | number };
  vehicle?: { id: string; licensePlate: string } | null;
  items: Array<{
    id: string;
    quantity: string | number;
    rate: string | number;
    lineTotal: string | number;
    gstRate: string | number;
    product: { name: string };
    godown: { name: string };
  }>;
};

export default function MobileAccountingQueues({ 
  customers, 
  suppliers,
  expenseCategories,
  banks,
  pendingProcurements = [],
  pendingPackingItems = [],
  pendingSales = []
}: { 
  customers: Customer[],
  suppliers: Supplier[],
  expenseCategories: ExpenseCategory[],
  banks: Bank[],
  pendingProcurements?: PendingProcurementBatch[],
  pendingPackingItems?: PendingPackingItem[],
  pendingSales?: PendingSalesInvoice[]
}) {
  const [submittingId, setSubmittingId] = useState<string | null>(null);
  const [skippedIds, setSkippedIds] = useState<string[]>([]);

  // --- STATES FOR MOBILE UX ---
  const router = useRouter();
  const [activePayment, setActivePayment] = useState<{ id: string; type: 'PADDY' | 'PACKING' | 'SALES'; maxAmount: number; title: string } | null>(null);
  const [expandedCardId, setExpandedCardId] = useState<string | null>(null);
  const [queueFilter, setQueueFilter] = useState<'ALL' | 'PADDY' | 'PACKING' | 'SALES'>('ALL');
  const [isSyncing, setIsSyncing] = useState(false);

  const filteredProcurements = pendingProcurements.filter(p => !skippedIds.includes(p.id) && (queueFilter === 'ALL' || queueFilter === 'PADDY'));
  const filteredPackingItems = pendingPackingItems.filter(p => !skippedIds.includes(p.id) && (queueFilter === 'ALL' || queueFilter === 'PACKING'));
  const filteredSales = pendingSales.filter(p => !skippedIds.includes(p.id) && (queueFilter === 'ALL' || queueFilter === 'SALES'));

  const totalPendingOutboundCount = filteredProcurements.length + filteredPackingItems.length;

  return (
    <div className="w-full">

      <div className="p-0">

        {/* MOBILE UI/UX: Sync Button & Filter Pills */}
        <div className="bg-[var(--surface-2)] p-4 rounded-xl border-2 border-[var(--border)] shadow-brutal-sm mb-6">
          <div className="flex justify-between items-center mb-3">
            <h3 className="font-black tracking-widest uppercase text-xs text-[var(--muted)] flex items-center">
              Action Queue
            </h3>
            <button 
              onClick={() => { setIsSyncing(true); router.refresh(); setTimeout(()=>setIsSyncing(false),1000); }}
              className="bg-[var(--surface)] text-[var(--text)] border-2 border-[var(--border)] px-3 py-1 rounded-full flex items-center font-black text-[10px] tracking-wider active:scale-95 transition-all shadow-sm"
            >
              <RefreshCw className={`w-3 h-3 mr-1.5 ${isSyncing ? 'animate-spin text-[var(--blue)]' : ''}`} />
              SYNC
            </button>
          </div>
          <div className="flex overflow-x-auto hide-scrollbar gap-2 pb-1">
            {['ALL', 'PADDY', 'PACKING', 'SALES'].map(pill => (
              <button 
                key={pill}
                onClick={() => setQueueFilter(pill as any)}
                className={`shrink-0 px-3.5 py-1.5 rounded-full font-black text-[10px] tracking-widest uppercase border-2 transition-all ${queueFilter === pill ? 'bg-[var(--ink)] text-[var(--gold)] border-[var(--ink)] shadow-sm' : 'bg-[var(--surface)] text-[var(--muted)] border-[var(--border)] hover:bg-[var(--surface-2)]'}`}
              >
                {pill} 
                <span className="ml-1.5 opacity-80">
                  {pill === 'ALL' && `(${totalPendingOutboundCount + filteredSales.length})`}
                  {pill === 'PADDY' && `(${filteredProcurements.length})`}
                  {pill === 'PACKING' && `(${filteredPackingItems.length})`}
                  {pill === 'SALES' && `(${filteredSales.length})`}
                </span>
              </button>
            ))}
          </div>
        </div>

        <div className="min-h-[500px]">
          <AnimatePresence mode="wait">

            {/* --- LIST VIEWS --- */}
            <motion.div 
              key="queues"
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              transition={{ duration: 0.2 }}
              className="space-y-6"
            >

                {totalPendingOutboundCount === 0 && filteredSales.length === 0 ? (
                  <div className="text-center py-16 text-[var(--muted)] bg-[var(--surface-2)] rounded-2xl border-2 border-dashed border-[var(--dust)] p-8">
                    <CheckCircle2 className="w-16 h-16 text-[var(--green)] mx-auto mb-4 opacity-75" />
                    <p className="font-display font-black text-2xl uppercase tracking-widest text-[var(--text)]">All Clear</p>
                    <p className="font-medium mt-2 text-sm">No pending payments or receipts in the queue.</p>
                  </div>
                ) : (
                  <div className="space-y-5">

                    {/* 1. Paddy Procurement Batches */}
                    {filteredProcurements.map((batch, idx) => {
                      const farmerPayable = Number(batch.farmerTotalPayable || 0);
                      const brokerCommission = Number(batch.brokerCommissionTotal || 0);
                      const totalOutbound = farmerPayable + brokerCommission;
                      const amountPaid = Number(batch.amountPaid || 0);
                      const remaining = Math.max(0, totalOutbound - amountPaid);
                      const percentPaid = totalOutbound > 0 ? Math.min(100, Math.round((amountPaid / totalOutbound) * 100)) : 0;
                      const isExpanded = expandedCardId === batch.id;

                      return (
                        <motion.div 
                          key={batch.id} 
                          initial={{ opacity: 0, y: 15 }}
                          animate={{ opacity: 1, y: 0 }}
                          transition={{ delay: idx * 0.05 }}
                          className="bg-[var(--surface)] border-2 border-[var(--border)] rounded-xl shadow-brutal-sm overflow-hidden"
                        >
                          {/* Card Top Section */}
                          <div className="p-4 sm:p-5 bg-[var(--surface)] space-y-4">
                            <div className="flex items-start justify-between gap-3">
                              <div>
                                <div className="flex items-center gap-2 mb-1.5 flex-wrap">
                                  <span className="font-display font-black text-[10px] bg-[var(--rust)] text-white px-2.5 py-0.5 rounded border border-[var(--ink)] uppercase tracking-wider flex items-center">
                                    <Truck className="w-3 h-3 mr-1" /> PADDY
                                  </span>
                                  <span className="text-[11px] font-bold text-[var(--muted)] font-mono">
                                    {new Date(batch.createdAt).toLocaleDateString("en-IN", { month: 'short', day: 'numeric', year: 'numeric' })}
                                  </span>
                                </div>
                                <h4 className="font-display font-black text-lg text-[var(--text)] tracking-tight">
                                  {batch.farmer?.name || batch.supplier.name}
                                </h4>
                                <p className="text-xs text-[var(--muted)] font-medium mt-0.5">
                                  {Number(batch.numberOfBags || 0)} bags • {Number(batch.netWeight || batch.grossWeight).toFixed(0)} kg ({batch.product?.name || 'Paddy'})
                                </p>
                              </div>

                              <div className="text-right shrink-0">
                                <span className="text-[10px] uppercase font-black tracking-widest text-[var(--muted)] block">Remaining</span>
                                <span className="font-display font-black text-xl text-[var(--red)] tabular-nums block">
                                  ₹{remaining.toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                                </span>
                                <span className="text-[11px] text-[var(--muted)] font-bold block mt-0.5">
                                  Total: ₹{totalOutbound.toLocaleString('en-IN')}
                                </span>
                              </div>
                            </div>

                            {/* Progress Bar */}
                            <div className="space-y-1">
                              <div className="flex justify-between text-[10px] font-black uppercase text-[var(--muted)]">
                                <span>Paid: ₹{amountPaid.toLocaleString('en-IN')} ({percentPaid}%)</span>
                                <span>Due: ₹{remaining.toLocaleString('en-IN')}</span>
                              </div>
                              <div className="w-full h-2.5 bg-[var(--surface-2)] border border-[var(--border)] rounded-full overflow-hidden flex">
                                <div style={{ width: `${percentPaid}%` }} className="bg-[var(--green)] h-full transition-all duration-300" />
                                <div style={{ width: `${100 - percentPaid}%` }} className="bg-[var(--red)] h-full transition-all duration-300 opacity-80" />
                              </div>
                            </div>

                            {/* Action Controls */}
                            <div className="flex items-center gap-3 pt-2">
                              <Button
                                onClick={() => setActivePayment({
                                  id: batch.id,
                                  type: 'PADDY',
                                  maxAmount: remaining,
                                  title: `Paddy Payment – ${batch.farmer?.name || batch.supplier.name}`
                                })}
                                className="flex-1 bg-[var(--red)] hover:bg-[#8B2E06] text-white py-3 font-black text-sm shadow-sm min-h-[46px]"
                              >
                                RECORD PAYMENT
                              </Button>

                              <button
                                onClick={() => setExpandedCardId(isExpanded ? null : batch.id)}
                                className="px-3 py-3 border-2 border-[var(--border)] rounded-lg text-xs font-black uppercase tracking-wider bg-[var(--surface-2)] text-[var(--text)] hover:bg-[var(--surface)] transition-colors min-h-[46px]"
                              >
                                {isExpanded ? 'Hide' : 'Details ▾'}
                              </button>
                            </div>
                          </div>

                          {/* Expandable Breakdown */}
                          <AnimatePresence>
                            {isExpanded && (
                              <motion.div
                                initial={{ height: 0, opacity: 0 }}
                                animate={{ height: 'auto', opacity: 1 }}
                                exit={{ height: 0, opacity: 0 }}
                                className="overflow-hidden border-t-2 border-dashed border-[var(--border)] bg-[var(--surface-2)]"
                              >
                                <div className="p-4 space-y-3 text-xs">
                                  <div className="flex justify-between border-b border-[var(--dust)] pb-2">
                                    <span className="text-[var(--muted)] font-bold">Farmer Name</span>
                                    <span className="font-black">{batch.farmer?.name || 'N/A'}</span>
                                  </div>
                                  <div className="flex justify-between border-b border-[var(--dust)] pb-2">
                                    <span className="text-[var(--muted)] font-bold">Broker Supplier</span>
                                    <span className="font-black">{batch.supplier.name}</span>
                                  </div>
                                  <div className="flex justify-between border-b border-[var(--dust)] pb-2">
                                    <span className="text-[var(--muted)] font-bold">Farmer Payable</span>
                                    <span className="font-black">₹{farmerPayable.toFixed(2)}</span>
                                  </div>
                                  {brokerCommission > 0 && (
                                    <div className="flex justify-between border-b border-[var(--dust)] pb-2">
                                      <span className="text-[var(--muted)] font-bold">Broker Commission</span>
                                      <span className="font-black">₹{brokerCommission.toFixed(2)}</span>
                                    </div>
                                  )}
                                  <div className="flex justify-between">
                                    <span className="text-[var(--muted)] font-bold">Godown Location</span>
                                    <span className="font-black text-[var(--blue)]">{batch.godown?.name || 'Main Godown'}</span>
                                  </div>
                                </div>
                              </motion.div>
                            )}
                          </AnimatePresence>
                        </motion.div>
                      );
                    })}

                    {/* 2. Packaging Material & Bag Procurements */}
                    {filteredPackingItems.map((pkg, idx) => {
                      const bags = Number(pkg.quantityBags);
                      const rate = Number(pkg.perBagRate);
                      const totalPayable = bags * rate;
                      const amountPaid = Number(pkg.amountPaid || 0);
                      const remaining = Math.max(0, totalPayable - amountPaid);
                      const percentPaid = totalPayable > 0 ? Math.min(100, Math.round((amountPaid / totalPayable) * 100)) : 0;
                      const isExpanded = expandedCardId === pkg.id;

                      return (
                        <motion.div 
                          key={pkg.id} 
                          initial={{ opacity: 0, y: 15 }}
                          animate={{ opacity: 1, y: 0 }}
                          transition={{ delay: (filteredProcurements.length + idx) * 0.05 }}
                          className="bg-[var(--surface)] border-2 border-[var(--border)] rounded-xl shadow-brutal-sm overflow-hidden"
                        >
                          {/* Card Top Section */}
                          <div className="p-4 sm:p-5 bg-[var(--surface)] space-y-4">
                            <div className="flex items-start justify-between gap-3">
                              <div>
                                <div className="flex items-center gap-2 mb-1.5 flex-wrap">
                                  <span className="font-display font-black text-[10px] bg-[var(--ink)] text-white px-2.5 py-0.5 rounded border border-[var(--ink)] uppercase tracking-wider flex items-center">
                                    <Package className="w-3 h-3 mr-1 text-[var(--gold)]" /> PACKING
                                  </span>
                                  <span className="text-[11px] font-bold text-[var(--muted)] font-mono">
                                    {new Date(pkg.createdAt).toLocaleDateString("en-IN", { month: 'short', day: 'numeric', year: 'numeric' })}
                                  </span>
                                </div>
                                <h4 className="font-display font-black text-lg text-[var(--text)] tracking-tight">
                                  {pkg.supplier?.name || 'General Vendor'}
                                </h4>
                                <p className="text-xs text-[var(--muted)] font-medium mt-0.5">
                                  Brand: {pkg.brandName} • {bags.toLocaleString()} bags @ ₹{rate.toFixed(2)} ({pkg.capacityKg}kg)
                                </p>
                              </div>

                              <div className="text-right shrink-0">
                                <span className="text-[10px] uppercase font-black tracking-widest text-[var(--muted)] block">Remaining</span>
                                <span className="font-display font-black text-xl text-[var(--red)] tabular-nums block">
                                  ₹{remaining.toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                                </span>
                                <span className="text-[11px] text-[var(--muted)] font-bold block mt-0.5">
                                  Total: ₹{totalPayable.toLocaleString('en-IN')}
                                </span>
                              </div>
                            </div>

                            {/* Progress Bar */}
                            <div className="space-y-1">
                              <div className="flex justify-between text-[10px] font-black uppercase text-[var(--muted)]">
                                <span>Paid: ₹{amountPaid.toLocaleString('en-IN')} ({percentPaid}%)</span>
                                <span>Due: ₹{remaining.toLocaleString('en-IN')}</span>
                              </div>
                              <div className="w-full h-2.5 bg-[var(--surface-2)] border border-[var(--border)] rounded-full overflow-hidden flex">
                                <div style={{ width: `${percentPaid}%` }} className="bg-[var(--green)] h-full transition-all duration-300" />
                                <div style={{ width: `${100 - percentPaid}%` }} className="bg-[var(--red)] h-full transition-all duration-300 opacity-80" />
                              </div>
                            </div>

                            {/* Action Controls */}
                            <div className="flex items-center gap-3 pt-2">
                              <Button
                                onClick={() => setActivePayment({
                                  id: pkg.id,
                                  type: 'PACKING',
                                  maxAmount: remaining,
                                  title: `Packing Bags – ${pkg.supplier?.name || 'General Vendor'}`
                                })}
                                className="flex-1 bg-[var(--ink)] hover:bg-black text-white py-3 font-black text-sm shadow-sm min-h-[46px]"
                              >
                                RECORD PAYMENT
                              </Button>

                              <button
                                onClick={() => setExpandedCardId(isExpanded ? null : pkg.id)}
                                className="px-3 py-3 border-2 border-[var(--border)] rounded-lg text-xs font-black uppercase tracking-wider bg-[var(--surface-2)] text-[var(--text)] hover:bg-[var(--surface)] transition-colors min-h-[46px]"
                              >
                                {isExpanded ? 'Hide' : 'Details ▾'}
                              </button>
                            </div>
                          </div>

                          {/* Expandable Breakdown */}
                          <AnimatePresence>
                            {isExpanded && (
                              <motion.div
                                initial={{ height: 0, opacity: 0 }}
                                animate={{ height: 'auto', opacity: 1 }}
                                exit={{ height: 0, opacity: 0 }}
                                className="overflow-hidden border-t-2 border-dashed border-[var(--border)] bg-[var(--surface-2)]"
                              >
                                <div className="p-4 space-y-3 text-xs">
                                  <div className="flex justify-between border-b border-[var(--dust)] pb-2">
                                    <span className="text-[var(--muted)] font-bold">Vendor Name</span>
                                    <span className="font-black">{pkg.supplier?.name || 'General Vendor'}</span>
                                  </div>
                                  <div className="flex justify-between border-b border-[var(--dust)] pb-2">
                                    <span className="text-[var(--muted)] font-bold">Brand & Capacity</span>
                                    <span className="font-black">{pkg.brandName} ({pkg.capacityKg} KG)</span>
                                  </div>
                                  <div className="flex justify-between border-b border-[var(--dust)] pb-2">
                                    <span className="text-[var(--muted)] font-bold">Quantity & Per Bag Rate</span>
                                    <span className="font-black">{bags.toLocaleString()} bags @ ₹{rate.toFixed(2)}</span>
                                  </div>
                                  <div className="flex justify-between">
                                    <span className="text-[var(--muted)] font-bold">Destination Godown</span>
                                    <span className="font-black text-[var(--blue)]">{pkg.godown.name}</span>
                                  </div>
                                </div>
                              </motion.div>
                            )}
                          </AnimatePresence>
                        </motion.div>
                      );
                    })}

                    {/* 3. Sales Invoices */}
                    {filteredSales.map((invoice, idx) => {
                      const grandTotal = Number(invoice.grandTotal);
                      const amountPaid = Number(invoice.amountPaid || 0);
                      const remaining = Math.max(0, grandTotal - amountPaid);
                      const percentPaid = grandTotal > 0 ? Math.min(100, Math.round((amountPaid / grandTotal) * 100)) : 0;
                      const isExpanded = expandedCardId === invoice.id;

                      return (
                        <motion.div 
                          key={invoice.id} 
                          initial={{ opacity: 0, y: 15 }}
                          animate={{ opacity: 1, y: 0 }}
                          transition={{ delay: idx * 0.05 }}
                          className="bg-[var(--surface)] border-2 border-[var(--border)] rounded-xl shadow-brutal-sm overflow-hidden"
                        >
                          {/* Card Top Section */}
                          <div className="p-4 sm:p-5 bg-[var(--surface)] space-y-4">
                            <div className="flex items-start justify-between gap-3">
                              <div>
                                <div className="flex items-center gap-2 mb-1.5 flex-wrap">
                                  <span className="font-display font-black text-[10px] bg-[var(--green)] text-[var(--text)] px-2.5 py-0.5 rounded border border-[var(--border)] uppercase tracking-wider flex items-center">
                                    <FileText className="w-3 h-3 mr-1" /> SALES #{invoice.invoiceNumber}
                                  </span>
                                  <span className="text-[11px] font-bold text-[var(--muted)] font-mono">
                                    {new Date(invoice.createdAt).toLocaleDateString("en-IN", { month: 'short', day: 'numeric', year: 'numeric' })}
                                  </span>
                                </div>
                                <h4 className="font-display font-black text-lg text-[var(--text)] tracking-tight">
                                  {invoice.customer.name}
                                </h4>
                                <p className="text-xs text-[var(--muted)] font-medium mt-0.5">
                                  Vehicle: {invoice.vehicle?.licensePlate || 'N/A'} • {invoice.items.length} Line item(s)
                                </p>
                              </div>

                              <div className="text-right shrink-0">
                                <span className="text-[10px] uppercase font-black tracking-widest text-[var(--muted)] block">Remaining</span>
                                <span className="font-display font-black text-xl text-[var(--green)] tabular-nums block">
                                  ₹{remaining.toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                                </span>
                                <span className="text-[11px] text-[var(--muted)] font-bold block mt-0.5">
                                  Total: ₹{grandTotal.toLocaleString('en-IN')}
                                </span>
                              </div>
                            </div>

                            {/* Progress Bar */}
                            <div className="space-y-1">
                              <div className="flex justify-between text-[10px] font-black uppercase text-[var(--muted)]">
                                <span>Received: ₹{amountPaid.toLocaleString('en-IN')} ({percentPaid}%)</span>
                                <span>Due: ₹{remaining.toLocaleString('en-IN')}</span>
                              </div>
                              <div className="w-full h-2.5 bg-[var(--surface-2)] border border-[var(--border)] rounded-full overflow-hidden flex">
                                <div style={{ width: `${percentPaid}%` }} className="bg-[var(--green)] h-full transition-all duration-300" />
                                <div style={{ width: `${100 - percentPaid}%` }} className="bg-[var(--gold)] h-full transition-all duration-300 opacity-80" />
                              </div>
                            </div>

                            {/* Action Controls */}
                            <div className="flex items-center gap-3 pt-2">
                              <Button
                                onClick={() => setActivePayment({
                                  id: invoice.id,
                                  type: 'SALES',
                                  maxAmount: remaining,
                                  title: `Sales Receipt – ${invoice.customer.name}`
                                })}
                                className="flex-1 bg-[var(--green)] hover:bg-[var(--green-light)] text-[var(--text)] py-3 font-black text-sm shadow-sm min-h-[46px]"
                              >
                                RECORD RECEIPT
                              </Button>

                              <button
                                onClick={() => setExpandedCardId(isExpanded ? null : invoice.id)}
                                className="px-3 py-3 border-2 border-[var(--border)] rounded-lg text-xs font-black uppercase tracking-wider bg-[var(--surface-2)] text-[var(--text)] hover:bg-[var(--surface)] transition-colors min-h-[46px]"
                              >
                                {isExpanded ? 'Hide' : 'Details ▾'}
                              </button>
                            </div>
                          </div>

                          {/* Expandable Breakdown */}
                          <AnimatePresence>
                            {isExpanded && (
                              <motion.div
                                initial={{ height: 0, opacity: 0 }}
                                animate={{ height: 'auto', opacity: 1 }}
                                exit={{ height: 0, opacity: 0 }}
                                className="overflow-hidden border-t-2 border-dashed border-[var(--border)] bg-[var(--surface-2)]"
                              >
                                <div className="p-4 space-y-3 text-xs">
                                  <div className="flex justify-between border-b border-[var(--dust)] pb-2">
                                    <span className="text-[var(--muted)] font-bold">Customer Name</span>
                                    <span className="font-black">{invoice.customer.name}</span>
                                  </div>
                                  <div className="flex justify-between border-b border-[var(--dust)] pb-2">
                                    <span className="text-[var(--muted)] font-bold">Vehicle License</span>
                                    <span className="font-black">{invoice.vehicle?.licensePlate || 'N/A'}</span>
                                  </div>
                                  <div className="pt-1">
                                    <span className="text-[var(--muted)] font-bold uppercase text-[10px] tracking-widest block mb-2">Invoice Line Items</span>
                                    <div className="space-y-1.5 max-h-32 overflow-y-auto pr-1">
                                      {invoice.items.map(item => (
                                        <div key={item.id} className="flex justify-between bg-[var(--surface)] p-2 rounded border border-[var(--dust)]">
                                          <span className="font-bold">{item.product.name} ({Number(item.quantity).toFixed(2)}kg)</span>
                                          <span className="font-black text-[var(--blue)]">₹{Number(item.lineTotal).toFixed(2)}</span>
                                        </div>
                                      ))}
                                    </div>
                                  </div>
                                </div>
                              </motion.div>
                            )}
                          </AnimatePresence>
                        </motion.div>
                      );
                    })}
                  </div>
                )}
              </motion.div>
          </AnimatePresence>
        </div>
      </div>

      {/* --- MOBILE UI/UX: BOTTOM SHEET FOR PAYMENTS --- */}
      <AnimatePresence>
        {activePayment && (
          <>
            <motion.div
              initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
              onClick={() => setActivePayment(null)}
              className="fixed inset-0 bg-black/60 z-[100] backdrop-blur-sm md:hidden"
            />
            <motion.div
              initial={{ y: '100%' }} animate={{ y: 0 }} exit={{ y: '100%' }} transition={{ type: 'spring', damping: 25, stiffness: 300 }}
              className="fixed bottom-0 left-0 right-0 max-h-[92vh] overflow-y-auto bg-[var(--bg)] rounded-t-3xl border-t-4 border-[var(--border)] z-[110] p-6 pb-20 shadow-2xl md:hidden"
            >
              <div className="flex justify-between items-center mb-6 border-b-2 border-dashed border-[var(--dust)] pb-4">
                <h2 className="font-black text-xl uppercase tracking-tight flex items-center text-[var(--text)]">
                  Record {activePayment.type === 'SALES' ? 'Receipt' : 'Payment'}
                </h2>
                <button onClick={() => setActivePayment(null)} className="p-2 bg-[var(--surface-2)] rounded-full text-[var(--muted)]">
                  <X className="w-5 h-5" />
                </button>
              </div>

              <div className="mb-4 p-4 bg-[var(--surface-2)] rounded-xl border-2 border-[var(--border)]">
                <span className="font-bold text-xs uppercase tracking-widest text-[var(--muted)] block mb-1">Target</span>
                <span className="font-black text-lg block">{activePayment.title}</span>
                <div className="flex justify-between items-center mt-2 pt-2 border-t border-[var(--dust)]">
                  <span className="font-bold text-xs uppercase text-[var(--muted)]">Pending Balance</span>
                  <span className={`font-black text-lg ${activePayment.type === 'SALES' ? 'text-[var(--green)]' : 'text-[var(--red)]'}`}>
                    ₹{activePayment.maxAmount.toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                  </span>
                </div>
              </div>

              <form action={async (formData: FormData) => {
                setSubmittingId(activePayment.id);
                try {
                  if (activePayment.type === 'PADDY') {
                    formData.append('batchId', activePayment.id);
                    await confirmProcurementPaymentAction(formData);
                  } else if (activePayment.type === 'PACKING') {
                    formData.append('packingItemId', activePayment.id);
                    await confirmPackingItemPaymentAction(formData);
                  } else if (activePayment.type === 'SALES') {
                    formData.append('invoiceId', activePayment.id);
                    await confirmSalesReceiptAction(formData);
                  }
                  toast.success(`${activePayment.type === 'SALES' ? 'Receipt' : 'Payment'} Confirmed!`);
                  setActivePayment(null);
                } catch (err) {
                  toast.error('Error confirming: ' + (err instanceof Error ? err.message : String(err)));
                } finally {
                  setSubmittingId(null);
                }
              }} className="space-y-4">
                <Input 
                  label={`Amount (${activePayment.type === 'SALES' ? 'Received' : 'Paid'}) ₹ *`}
                  type="number" step="0.01" name="amount" required max={activePayment.maxAmount} placeholder="e.g. 0.00"
                  className={`${activePayment.type === 'SALES' ? 'text-[var(--green)]' : 'text-[var(--red)]'} font-black text-xl`} 
                />
                <Select label="Payment Mode *" name="mode" required>
                  <option value="CASH">Cash</option>
                  <option value="BANK">Bank / Cheque</option>
                  <option value="UPI">UPI</option>
                </Select>
                <Select label="Bank Account (if applicable)" name="bankId">
                  <option value="">Select Bank...</option>
                  {banks.map(b => (
                    <option key={b.id} value={b.id}>{b.bankName} (...{b.accountNumber.slice(-4)})</option>
                  ))}
                </Select>
                <Input label="Reference No." type="text" name="referenceNumber" placeholder="Cheque / UTR" />
                <div className="pt-3 pb-6">
                  <Button
                    type="submit"
                    variant="primary"
                    disabled={submittingId === activePayment.id}
                    className={`w-full min-h-[52px] py-4 text-base font-black shadow-brutal-sm ${activePayment.type === 'SALES' ? 'bg-[var(--green)] hover:bg-[var(--green-light)] text-[var(--text)]' : 'bg-[var(--red)] hover:bg-[#8B2E06] text-white'}`}
                  >
                    {submittingId === activePayment.id ? 'PROCESSING...' : `CONFIRM ${activePayment.type === 'SALES' ? 'RECEIPT' : 'PAYMENT'}`}
                  </Button>
                </div>
              </form>
            </motion.div>
          </>
        )}
      </AnimatePresence>

    </div>
  );
}

