                  { id: 'WAGE', label: 'Wage', icon: '💰' },
                  { id: 'ADVANCE', label: 'Advance', icon: '💵' },
                  { id: 'SETTLE', label: 'Settle', icon: '✅' },
                  { id: 'HISTORY', label: 'History', icon: '📋' },
                ].map(tab => (
                  <button key={tab.id}
                    onClick={() => { setActiveTab(tab.id as any); resetForms(); }}
                    className={`flex-1 py-3 text-[11px] font-black uppercase tracking-wider transition-all border-b-2 ${activeTab === tab.id ? 'border-[#F5A623] text-[#F5A623]' : 'border-transparent text-neutral-500 hover:text-neutral-300'}`}>
                    <span className="mr-1">{tab.icon}</span>
                    <span className="hidden sm:inline">{tab.label}</span>
                  </button>
                ))}
              </div>

              {/* Scrollable Content */}
              <div className="flex-1 overflow-y-auto p-5 pb-6">

                {/* WAGE TAB */}
                {activeTab === 'WAGE' && (
                  <form onSubmit={handleWageSubmit} className="space-y-5">
                    <div className="bg-[#1A1A1A] p-4 rounded-2xl border border-neutral-800">
                      <p className="text-xs text-neutral-400 leading-relaxed">
                        Credit wage to ledger. This will <strong className="text-red-400">increase</strong> the amount you owe this worker.
                      </p>
                    </div>

                    <div>
                      <label className="text-[10px] font-black uppercase tracking-widest text-neutral-400 block mb-2">Work Type (Optional)</label>
                      <input type="text" value={workType} onChange={e => setWorkType(e.target.value)}
                        placeholder="e.g. Unloading Paddy"
                        className="w-full bg-[#1A1A1A] border border-neutral-700 rounded-xl px-4 py-3.5 text-white font-semibold placeholder:text-neutral-600 focus:outline-none focus:border-[#F5A623] transition-colors" />
                    </div>

                    <div>
                      <label className="text-[10px] font-black uppercase tracking-widest text-neutral-400 block mb-2">Total Wage (₹) *</label>
                      <input type="number" step="0.01" required value={totalWageFlat} onChange={e => setTotalWageFlat(e.target.value)}
                        placeholder="0.00" inputMode="decimal"
                        className="w-full bg-[#1A1A1A] border border-neutral-700 rounded-xl px-4 py-4 text-sky-400 font-mono font-black text-3xl tabular-nums placeholder:text-neutral-700 focus:outline-none focus:border-sky-500 transition-colors" />
                    </div>

                    <button type="submit" disabled={isSubmitting || calculatedTotal <= 0}
                      className="w-full py-4 bg-sky-500 hover:bg-sky-400 text-white font-black text-base uppercase tracking-wider rounded-2xl active:scale-95 transition-all disabled:opacity-50 shadow-lg shadow-sky-500/20">
                      {isSubmitting ? 'Recording...' : `Credit ₹${calculatedTotal.toFixed(2)}`}
                    </button>
                  </form>
                )}

                {/* ADVANCE TAB */}
                {activeTab === 'ADVANCE' && (
                  <form onSubmit={handleAdvanceSubmit} className="space-y-5">
                    <div className="bg-amber-950/30 p-4 rounded-2xl border border-amber-900/40">
                      <p className="text-xs text-amber-200/70 leading-relaxed">
                        Issue a cash advance. This will <strong className="text-amber-300">decrease</strong> the amount you owe this worker.
                      </p>
                    </div>

                    <div>
                      <label className="text-[10px] font-black uppercase tracking-widest text-neutral-400 block mb-2">Advance Amount (₹) *</label>
                      <input type="number" step="0.01" required value={amount} onChange={e => setAmount(e.target.value)}
                        placeholder="0.00" inputMode="decimal"
                        className="w-full bg-[#1A1A1A] border border-neutral-700 rounded-xl px-4 py-4 text-amber-400 font-mono font-black text-3xl tabular-nums placeholder:text-neutral-700 focus:outline-none focus:border-amber-500 transition-colors" />
                    </div>

                    <div>
                      <label className="text-[10px] font-black uppercase tracking-widest text-neutral-400 block mb-2">Reason *</label>
                      <input type="text" required value={description} onChange={e => setDescription(e.target.value)}
                        placeholder="e.g. Groceries, Festival Advance"
                        className="w-full bg-[#1A1A1A] border border-neutral-700 rounded-xl px-4 py-3.5 text-white font-semibold placeholder:text-neutral-600 focus:outline-none focus:border-amber-500 transition-colors" />
                    </div>

                    <div>
                      <label className="text-[10px] font-black uppercase tracking-widest text-neutral-400 block mb-2">Paid From</label>
                      <select value={selectedBankId} onChange={e => setSelectedBankId(e.target.value)}
                        className="w-full bg-[#1A1A1A] border border-neutral-700 rounded-xl px-4 py-3.5 text-white font-semibold focus:outline-none focus:border-amber-500 transition-colors">
                        <option value="">Cash Account</option>
                        {banks.map(b => <option key={b.id} value={b.id}>{b.bankName} - ...{b.accountNumber?.slice(-4)}</option>)}
                      </select>
                    </div>

                    <button type="submit" disabled={isSubmitting}
                      className="w-full py-4 bg-amber-500 hover:bg-amber-400 text-black font-black text-base uppercase tracking-wider rounded-2xl active:scale-95 transition-all disabled:opacity-50">
                      {isSubmitting ? 'Processing...' : 'Issue Advance'}
                    </button>
                  </form>
                )}

                {/* SETTLE TAB */}
                {activeTab === 'SETTLE' && (
                  <form onSubmit={handleSettleSubmit} className="space-y-5">
                    <div className="bg-emerald-950/30 p-4 rounded-2xl border border-emerald-900/40">
                      <p className="text-xs text-emerald-200/70 leading-relaxed">
                        Pay off outstanding balance. This will <strong className="text-emerald-300">settle</strong> what you owe this worker.
                      </p>
                    </div>

                    <div>
                      <label className="text-[10px] font-black uppercase tracking-widest text-neutral-400 block mb-2">Payment Amount (₹) *</label>
                      <input type="number" step="0.01" required value={amount} onChange={e => setAmount(e.target.value)}
                        placeholder="0.00" inputMode="decimal"
                        className="w-full bg-[#1A1A1A] border border-neutral-700 rounded-xl px-4 py-4 text-emerald-400 font-mono font-black text-3xl tabular-nums placeholder:text-neutral-700 focus:outline-none focus:border-emerald-500 transition-colors" />
                    </div>

                    <div>
                      <label className="text-[10px] font-black uppercase tracking-widest text-neutral-400 block mb-2">Source Account</label>
                      <select value={selectedBankId} onChange={e => setSelectedBankId(e.target.value)}
                        className="w-full bg-[#1A1A1A] border border-neutral-700 rounded-xl px-4 py-3.5 text-white font-semibold focus:outline-none focus:border-emerald-500 transition-colors">
                        <option value="">Cash Account</option>
                        {banks.map(b => <option key={b.id} value={b.id}>{b.bankName} - ...{b.accountNumber?.slice(-4)}</option>)}
                      </select>
                    </div>

                    <button type="submit" disabled={isSubmitting}
                      className="w-full py-4 bg-emerald-500 hover:bg-emerald-400 text-white font-black text-base uppercase tracking-wider rounded-2xl active:scale-95 transition-all disabled:opacity-50">
                      {isSubmitting ? 'Processing...' : 'Pay Now'}
                    </button>
                  </form>
                )}

                {/* HISTORY TAB */}
                {activeTab === 'HISTORY' && (
                  <div className="space-y-3 pb-4">
                    {isLoadingHistory ? (
                      <div className="py-12 text-center">
                        <div className="w-8 h-8 border-2 border-[#F5A623] border-t-transparent rounded-full animate-spin mx-auto mb-3" />
                        <span className="text-xs font-black uppercase tracking-widest text-neutral-500">Loading History...</span>
                      </div>
                    ) : history.length === 0 ? (
                      <div className="py-12 text-center text-neutral-600">
                        <History className="w-10 h-10 mx-auto mb-3 opacity-20" />
                        <span className="text-xs font-bold uppercase">No records found.</span>
                      </div>
                    ) : (
                      history.map(item => (
                        <div key={item.id} className="flex items-center justify-between p-3.5 bg-[#1A1A1A] rounded-2xl border border-neutral-800">
                          <div className="flex items-start gap-3">
                            <div className={`w-8 h-8 rounded-xl flex items-center justify-center shrink-0 ${item.amount > 0 ? 'bg-red-500/20' : 'bg-emerald-500/20'}`}>
                              {item.amount > 0 ? (
                                <TrendingUp className="w-4 h-4 text-red-400" />
                              ) : (
                                <TrendingDown className="w-4 h-4 text-emerald-400" />
                              )}
                            </div>
                            <div>
                              <p className="font-bold text-white text-sm">{item.desc || item.type}</p>
                              <div className="flex items-center gap-2 mt-0.5">
                                <span className="text-[10px] text-neutral-500">{new Date(item.date).toLocaleDateString('en-IN')}</span>
                                <span className={`text-[9px] font-black uppercase px-1.5 py-0.5 rounded ${item.amount > 0 ? 'bg-red-500/20 text-red-400' : 'bg-emerald-500/20 text-emerald-400'}`}>
                                  {item.type}
                                </span>
                              </div>
                            </div>
                          </div>
                          <span className={`font-mono font-black text-base tabular-nums ${item.amount > 0 ? 'text-red-400' : 'text-emerald-400'}`}>
                            {item.amount > 0 ? '+' : ''}{item.amount.toFixed(2)}
                          </span>
                        </div>
                      ))
                    )}
                  </div>
                )}
              </div>
            </motion.div>
          </>
        )}
      </AnimatePresence>
    </div>
  );
}

'use client';

import { Tags, Edit2, Trash2, ArrowRight, Check, X } from 'lucide-react';
import { Input, Select } from '@/components/ui/Input';
import Link from 'next/link';
import { updatePackingItemAction, deletePackingItemAction } from "@/app/actions/packingItem";
import SubmitWithConfirm from "@/components/SubmitWithConfirm";
import { Badge } from '@/components/ui/Badge';
import { Button } from '@/components/ui/Button';

type Godown = { id: string; name: string };
type Supplier = { id: string; name: string };

type PackingItemData = {
  id: string;
  brandName: string;
  capacityKg: number | string | { toString(): string };
  quantityBags: number | string | { toString(): string };
  perBagRate: number | string | { toString(): string };
  godownId: string;
  hsnCode?: string | null;
  status?: string;
  godown: { name: string };
  supplier?: { id: string; name: string } | null;
};

export default function PackingInventorySection({
  packingItems,
  godowns,
  editPackingId,
}: {
  packingItems: PackingItemData[];
  godowns: Godown[];
  suppliers?: Supplier[];
  editPackingId?: string;
}) {
  // Calculate totals for active paid stock
  const paidPackingItems = packingItems.filter(item => item.status === 'PAID');
  const totalBagsInStock = paidPackingItems.reduce((acc, item) => acc + Number(item.quantityBags), 0);
  const totalPackingValue = paidPackingItems.reduce((acc, item) => acc + (Number(item.quantityBags) * Number(item.perBagRate)), 0);

  return (
    <div className="mb-12 space-y-6 animate-fade-up">

      {/* Section Header with Stats & Action */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
        <div>
          <h2 className="font-display font-black text-2xl uppercase tracking-widest flex items-center text-[var(--text)]">
            <Tags className="w-6 h-6 mr-3 text-[var(--blue)]" /> Packaging Material
          </h2>
          <p className="text-sm font-bold text-[var(--muted)] mt-1 uppercase tracking-wider">
            Real-time stock of branded packaging bags. Add new stock strictly via Procurement Hub.
          </p>
        </div>

        <div className="flex flex-wrap items-center gap-4 w-full md:w-auto">
          <div className="card-brutal p-3 bg-[var(--surface)] text-right min-w-[140px]">
            <span className="text-[10px] font-black uppercase tracking-widest text-[var(--muted)] block">Total Bags</span>
            <span className="text-2xl font-black tabular-nums text-[var(--blue)]">
              {totalBagsInStock.toLocaleString()} <span className="text-xs font-bold text-[var(--text)]">Bags</span>
            </span>
          </div>

          <div className="card-brutal p-3 bg-[var(--surface)] text-right min-w-[140px]">
            <span className="text-[10px] font-black uppercase tracking-widest text-[var(--muted)] block">Stock Value</span>
            <span className="text-2xl font-black tabular-nums text-[var(--green)]">
              ₹ {totalPackingValue.toLocaleString('en-IN', { minimumFractionDigits: 2 })}
            </span>
          </div>

          <Link href="/operator/procurement?tab=packaging" className="flex-1 md:flex-none">
            <Button variant="primary" className="w-full bg-[var(--ink)] text-white">
              PROCURE BAGS <ArrowRight className="w-4 h-4 ml-2" />
            </Button>
          </Link>
        </div>
      </div>

      {/* FULL-WIDTH STOCK TABLE */}
      <div className="lg:col-span-2 mt-6">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 animate-fade-up">
          {packingItems.map((item) => {
            const totalItemVal = Number(item.quantityBags) * Number(item.perBagRate);
            const isEditing = editPackingId === item.id;
            const isPendingCashier = item.status === 'FINALIZED';

            return (
              <div key={item.id} className="card-brutal p-4 bg-[var(--surface)] hover:bg-[var(--surface-2)] transition-colors group flex flex-col justify-between">
                {isEditing ? (
                  <form action={updatePackingItemAction} className="flex flex-col gap-4">
                    <input type="hidden" name="id" value={item.id} />
                    <Input type="text" label="Brand Name" name="brandName" defaultValue={item.brandName} required />
                    <div className="grid grid-cols-2 gap-2">
                      <Input type="number" label="Size (KG)" step="0.01" name="capacityKg" defaultValue={item.capacityKg.toString()} required className="text-right" />
                      <Input type="number" label="Stock Bags" step="1" name="quantityBags" defaultValue={item.quantityBags.toString()} required className="text-right" />
                    </div>
                    <div className="grid grid-cols-2 gap-2">
                      <Input type="number" label="Rate/Bag" step="0.01" name="perBagRate" defaultValue={item.perBagRate.toString()} required className="text-right" />
                      <Select label="Godown" name="godownId" defaultValue={item.godownId} required>
                        {godowns.map(g => (
                          <option key={g.id} value={g.id}>{g.name}</option>
                        ))}
                      </Select>
                    </div>
                    <div className="flex gap-2 justify-end mt-2">
                      <Link href="/admin/inventory" className="btn btn-ghost h-10 px-4">CANCEL</Link>
                      <Button type="submit" variant="green" className="h-10 px-4">SAVE</Button>
                    </div>
                  </form>
                ) : (
                  <>
                    <div>
                      <div className="flex justify-between items-start mb-4">
                        <Badge variant="blue">{Number(item.capacityKg)} KG</Badge>
                        <div className="flex gap-2 sm:opacity-0 group-hover:opacity-100 transition-opacity">
                          <Link href={`/admin/inventory?editPackingId=${item.id}`} className="w-8 h-8 bg-[var(--surface)] border-2 border-[var(--border)] flex items-center justify-center shadow-[2px_2px_0px_#0D0D0B] active:translate-y-[2px] active:shadow-none hover:bg-[var(--blue)] hover:text-white transition-colors" title="Edit Item">
                            <Edit2 className="w-4 h-4" />
                          </Link>
                          <form action={deletePackingItemAction}>
                            <input type="hidden" name="id" value={item.id} />
                            <SubmitWithConfirm confirmMessage="Are you sure you want to delete this packing material item?">
                              <Trash2 className="w-4 h-4 text-[var(--red)] hover:scale-110 transition-transform" />
                            </SubmitWithConfirm>
                          </form>
                        </div>
                      </div>

                      <div className="font-black text-xl uppercase tracking-wider mb-1">
                        {item.brandName}
                      </div>
                      <div className="text-sm font-bold text-[var(--muted)] flex justify-between items-center mb-4 pb-4 border-b-2 border-dashed border-[var(--dust)]">
                        <span>{item.supplier ? `Vendor: ${item.supplier.name}` : 'No Vendor'}</span>
                        <div className="text-right">
                          <span className="font-bold uppercase tracking-wider block text-xs">{item.godown.name}</span>
                          {isPendingCashier ? (
                            <Badge variant="orange" className="mt-1">Pending Cashier</Badge>
                          ) : (
                            <Badge variant="green" className="mt-1">Active Stock</Badge>
                          )}
                        </div>
                      </div>
                    </div>

                    <div className="flex justify-between items-end mt-2">
                      <div>
                        <span className="text-[10px] font-black uppercase tracking-widest text-[var(--muted)] block">Stock Bags @ ₹{Number(item.perBagRate).toFixed(2)}</span>
                        <span className="font-black text-2xl tabular-nums text-[var(--blue)]">{Number(item.quantityBags).toLocaleString()}</span>
                      </div>
                      <div className="text-right">
                        <span className="text-[10px] font-black uppercase tracking-widest text-[var(--muted)] block">Total Value</span>
                        <span className="font-black text-2xl tabular-nums text-[var(--green)]">₹ {totalItemVal.toLocaleString('en-IN', { minimumFractionDigits: 2 })}</span>
                      </div>
                    </div>
                  </>
                )}
              </div>
            );
          })}

          {packingItems.length === 0 && (
            <div className="col-span-full p-8 text-center font-bold text-[var(--muted)] uppercase tracking-wider border-4 border-dashed border-[var(--dust)]">
              No packing material stock added yet. Log new bag inventory via Procurement Hub.
            </div>
          )}
        </div>
      </div>

    </div>
  );
}

