'use client';

import { useState, useMemo, useEffect } from 'react';
import { toast } from 'sonner';
import { Users, Calculator, Plus, X, CreditCard, Banknote, History } from 'lucide-react';
import { recordWageAction, getLaborerHistoryAction, issueAdvanceAction, settleLaborerPaymentAction } from '@/app/actions/payroll';
import { createLaborerAction } from '@/app/actions/masterData';
import MobilePayrollDesk from '@/components/MobilePayrollDesk';
import { Input, Select } from '@/components/ui/Input';
import { Button } from '@/components/ui/Button';
import { Modal } from '@/components/ui/Modal';
import { Badge } from '@/components/ui/Badge';
import { motion, AnimatePresence } from 'framer-motion';

type Laborer = { id: string; name: string; type: string; balance: number | string | { toString(): string } };
type SelectOption = { id: string; bankName?: string; accountNumber?: string };

type HistoryItem = { id: string; date: Date; type: string; desc: string; amount: number };

export default function PayrollForm({ laborers, banks = [] }: { laborers: Laborer[], banks?: SelectOption[] }) {
  const [localLaborers, setLocalLaborers] = useState(laborers);
  const [laborerId, setLaborerId] = useState('');
  const [workType, setWorkType] = useState('');
  const [totalWageFlat, setTotalWageFlat] = useState('');

  const [isSubmitting, setIsSubmitting] = useState(false);

  const [isAddModalOpen, setAddModalOpen] = useState(false);
  const [isAddingLaborer, setIsAddingLaborer] = useState(false);
  const [newLaborerName, setNewLaborerName] = useState('');
  const [newLaborerType, setNewLaborerType] = useState('HAMALI');
  const [newLaborerContact, setNewLaborerContact] = useState('');

  // New features state
  const [isAdvanceModalOpen, setIsAdvanceModalOpen] = useState(false);
  const [isSettleModalOpen, setIsSettleModalOpen] = useState(false);
  const [amount, setAmount] = useState('');
  const [description, setDescription] = useState('');
  const [selectedBankId, setSelectedBankId] = useState('');

  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [isLoadingHistory, setIsLoadingHistory] = useState(false);

  useEffect(() => {
    if (laborerId) {
      setIsLoadingHistory(true);
      getLaborerHistoryAction(laborerId).then(data => {
        setHistory(data);
        setIsLoadingHistory(false);
      });
    } else {
      setHistory([]);
    }
  }, [laborerId]);

  const calculatedTotal = useMemo(() => {
    return Number(totalWageFlat) || 0;
  }, [totalWageFlat]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedTotal <= 0) {
      toast.error("Total wage must be greater than zero.");
      return;
    }

    setIsSubmitting(true);
    try {
      const formData = new FormData();
      formData.append('laborerId', laborerId);
      if (workType) formData.append('workType', workType);
      formData.append('totalWage', totalWageFlat);

      await recordWageAction(formData);
      toast.success('Wage recorded successfully! Balance updated.');

      setTotalWageFlat('');
      setWorkType('');
      window.location.reload();
    } catch (error) {
      toast.error('Error recording wage: ' + (error instanceof Error ? error.message : String(error)));
      setIsSubmitting(false);
    }
  };

  const handleAddLaborer = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsAddingLaborer(true);
    try {
      const formData = new FormData();
      formData.append('name', newLaborerName);
      formData.append('type', newLaborerType);
      if (newLaborerContact) formData.append('contact', newLaborerContact);

      const newLaborer = await createLaborerAction(formData);

      const laborerObj = {
        id: newLaborer.id,
        name: newLaborer.name,
        type: newLaborerType,
        balance: 0
      };

      setLocalLaborers(prev => [...prev, laborerObj]);
      setLaborerId(newLaborer.id);
      setAddModalOpen(false);
      setNewLaborerName('');
      setNewLaborerContact('');
    } catch (error) {
      toast.error('Error adding laborer: ' + (error instanceof Error ? error.message : String(error)));
    } finally {
      setIsAddingLaborer(false);
    }
  };

  const handleAdvanceSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    try {
      const formData = new FormData();
      formData.append('laborerId', laborerId);
      formData.append('amount', amount);
      formData.append('description', description);
      if (selectedBankId) formData.append('bankId', selectedBankId);

      await issueAdvanceAction(formData);
      toast.success('Advance issued successfully!');
      window.location.reload();
    } catch (error) {
      toast.error('Error: ' + (error instanceof Error ? error.message : String(error)));
      setIsSubmitting(false);
    }
  };

  const handleSettleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    try {
      const formData = new FormData();
      formData.append('laborerId', laborerId);
      formData.append('amount', amount);
      if (selectedBankId) formData.append('bankId', selectedBankId);

      await settleLaborerPaymentAction(formData);
      toast.success('Payment settled successfully!');
      window.location.reload();
    } catch (error) {
      toast.error('Error: ' + (error instanceof Error ? error.message : String(error)));
      setIsSubmitting(false);
    }
  };

  const selectedLaborer = localLaborers.find(l => l.id === laborerId);

  return (
    <>
      <div className="md:hidden">
        <MobilePayrollDesk laborers={laborers} banks={banks} />
      </div>
      <div className="hidden md:block max-w-4xl mx-auto space-y-8 mt-6">

        <div className="card-brutal p-0 overflow-hidden">
          <div className="bg-[var(--gold)] p-6 sm:p-10 text-[var(--text)] border-b-2 border-[var(--border)]">
            <h2 className="font-display font-black text-3xl flex items-center tracking-tight">
              <Users className="h-8 w-8 mr-3" />
              PAYROLL DESK
            </h2>
            <p className="mt-2 text-[var(--text)]/80 font-bold uppercase tracking-wider text-sm">
              Log piece-rate wages and manage labor ledgers
            </p>
          </div>

          <div className="p-6 sm:p-10">
            <form className="space-y-8 pb-28 sm:pb-0" onSubmit={handleSubmit}>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8 stagger">
                <div className="flex gap-2 items-end animate-fade-up">
                  <Select
                    label="Laborer / Gang *"
                    value={laborerId} 
                    onChange={(e) => setLaborerId(e.target.value)} 
                    required
                  >
                    <option value="">Select Laborer...</option>
                    {localLaborers.map(l => <option key={l.id} value={l.id}>{l.name} ({l.type})</option>)}
                  </Select>
                  <Button type="button" variant="ghost" onClick={() => setAddModalOpen(true)} className="px-3 mb-[2px]">
                    <Plus className="w-5 h-5" />
                  </Button>
                </div>

                <AnimatePresence>
                  {selectedLaborer && (
                    <motion.div 
                      initial={{ opacity: 0, x: 20 }}
                      animate={{ opacity: 1, x: 0 }}
                      exit={{ opacity: 0, scale: 0.95 }}
                      className="flex flex-col gap-3"
                    >
                      <div className="w-full p-4 bg-[var(--surface-2)] border-2 border-[var(--border)] shadow-brutal-sm flex justify-between items-center">
                        <div>
                          <span className="font-display font-bold uppercase tracking-widest text-[var(--muted)] text-[10px] block mb-1">Current Ledger Balance</span>
                          <span className={`text-2xl font-black tabular-nums ${Number(selectedLaborer.balance) > 0 ? 'text-[var(--red)]' : 'text-[var(--green)]'}`}>
                            ₹{Number(selectedLaborer.balance).toFixed(2)}
                          </span>
                        </div>
                      </div>
                      <div className="flex gap-3">
                        <Button
                          type="button"
                          variant="ghost"
                          onClick={() => { setAmount(''); setDescription(''); setIsAdvanceModalOpen(true); }}
                          className="flex-1 bg-amber-200 border-amber-900 text-amber-900"
                        >
                          <Banknote className="h-4 w-4 mr-2" /> ADVANCE
                        </Button>
                        <Button
                          type="button"
                          variant="primary"
                          onClick={() => { setAmount(''); setIsSettleModalOpen(true); }}
                          className="flex-1 bg-[var(--green)]"
                        >
                          <CreditCard className="h-4 w-4 mr-2" /> SETTLE
                        </Button>
                      </div>
                    </motion.div>
                  )}
                </AnimatePresence>
              </div>

              <div className="animate-fade-up">
                <Input
                  label="Work Type (Optional)"
                  type="text"
                  value={workType}
                  onChange={(e) => setWorkType(e.target.value)}
                  placeholder="e.g. Unloading, General Labor"
                />
              </div>

              <div className="pt-8 border-t-2 border-[var(--border)] animate-fade-up">
                <h3 className="font-display font-black text-xl text-[var(--text)] uppercase flex items-center mb-6">
                  <Calculator className="h-5 w-5 mr-2 text-[var(--blue)]" /> WAGE CALCULATION
                </h3>

                <Input 
                  label="Total Flat Wage (₹) *"
                  type="number" 
                  step="0.01" 
                  required 
                  value={totalWageFlat} 
                  onChange={(e) => setTotalWageFlat(e.target.value)} 
                  className="text-2xl font-black text-[var(--blue)] tabular-nums p-4 h-auto"
                  placeholder="0.00" 
                />
              </div>

              {/* Sticky Action Bar on Mobile */}
              <div className="fixed bottom-[70px] sm:static sm:bottom-auto left-0 w-full z-50 p-4 sm:p-6 bg-[var(--charcoal)] border-t-4 sm:border-4 border-[var(--blue)] shadow-[0_-8px_20px_rgba(0,0,0,0.5)] sm:shadow-brutal text-white flex flex-col sm:flex-row justify-between items-center mt-0 sm:mt-8 gap-4 sm:gap-0 sm:rounded-sm">
                <div className="flex justify-between sm:justify-start w-full sm:w-auto items-center gap-4">
                  <span className="font-display font-bold uppercase tracking-wider text-sm sm:text-base">Total Wage</span>
                  <span className="text-2xl sm:text-3xl font-black tabular-nums text-[var(--blue)]">₹{calculatedTotal.toFixed(2)}</span>
                </div>

                <div className="w-full sm:w-auto">
                  <Button
                    type="submit"
                    variant="primary"
                    disabled={isSubmitting || !laborerId || calculatedTotal <= 0}
                    className="w-full sm:w-auto py-3 sm:py-2 text-lg sm:text-sm"
                  >
                    {isSubmitting ? 'RECORDING...' : 'CREDIT LEDGER'}
                  </Button>
                </div>
              </div>
            </form>
          </div>
        </div>

        {/* Recent History Table */}
        <AnimatePresence>
          {laborerId && (
            <motion.div 
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              className="card-brutal p-0 overflow-hidden"
            >
              <div className="bg-[var(--charcoal)] p-4 sm:p-6 text-white border-b-2 border-[var(--border)]">
                <h3 className="font-display font-black text-xl flex items-center tracking-tight">
                  <History className="h-5 w-5 mr-2 text-[var(--gold)]" /> LEDGER HISTORY
                </h3>
              </div>

              <div className="p-0">
                {isLoadingHistory ? (
                  <div className="p-8 text-center font-display font-bold text-[var(--muted)] animate-pulse">LOADING HISTORY...</div>
                ) : history.length === 0 ? (
                  <div className="p-8 text-center font-display font-bold uppercase text-[var(--muted)]">
                    No records found for this laborer.
                  </div>
                ) : (
                  <div className="overflow-x-auto">
                    <table className="table-brutal">
                      <thead>
                        <tr>
                          <th>Date</th>
                          <th>Type</th>
                          <th>Description</th>
                          <th className="text-right">Amount (₹)</th>
                        </tr>
                      </thead>
                      <tbody>
                        {history.map((item) => (
                          <tr key={item.id}>
                            <td className="whitespace-nowrap font-bold text-sm">
                              {new Date(item.date).toLocaleDateString()}
                            </td>
                            <td>
                              <Badge variant={item.amount > 0 ? 'green' : 'red'}>
                                {item.type}
                              </Badge>
                            </td>
                            <td className="text-sm font-medium">{item.desc}</td>
                            <td className={`text-right font-black tabular-nums ${item.amount > 0 ? 'text-[var(--green)]' : 'text-[var(--red)]'}`}>
                              {item.amount > 0 ? '+' : ''}{item.amount.toFixed(2)}
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        {/* Advance Modal */}
        <Modal isOpen={isAdvanceModalOpen} onClose={() => setIsAdvanceModalOpen(false)} title="ISSUE CASH ADVANCE">
          <form onSubmit={handleAdvanceSubmit} className="space-y-6">
            <Input
              label="Amount (₹) *"
              type="number" step="0.01" required value={amount} onChange={e => setAmount(e.target.value)}
              className="text-xl font-bold"
            />
            <Input
              label="Description (Reason) *"
              type="text" required value={description} onChange={e => setDescription(e.target.value)}
              placeholder="e.g. Weekly advance for groceries"
            />
            <Select 
              label="Paid From (Source)"
              value={selectedBankId} onChange={(e) => setSelectedBankId(e.target.value)}
            >
              <option value="">Cash Account</option>
              {banks.map(b => (
                <option key={b.id} value={b.id}>{b.bankName} - {b.accountNumber}</option>
              ))}
            </Select>
            <div className="pt-4 flex justify-end gap-3 border-t-2 border-[var(--border)]">
              <Button type="button" variant="ghost" onClick={() => setIsAdvanceModalOpen(false)}>CANCEL</Button>
              <Button type="submit" variant="primary" disabled={isSubmitting}>ISSUE ADVANCE</Button>
            </div>
          </form>
        </Modal>

        {/* Settle Modal */}
        <Modal isOpen={isSettleModalOpen} onClose={() => setIsSettleModalOpen(false)} title="SETTLE PAYMENT">
          <form onSubmit={handleSettleSubmit} className="space-y-6">
            <div className="p-4 bg-[var(--green)] text-white font-bold border-2 border-[var(--border)] shadow-brutal-sm text-sm">
              Paying off the ledger balance decreases the amount owed to this laborer.
            </div>
            <Input
              label="Payment Amount (₹) *"
              type="number" step="0.01" required value={amount} onChange={e => setAmount(e.target.value)}
              className="text-xl font-bold"
            />
            <Select 
              label="Source Account"
              value={selectedBankId} onChange={(e) => setSelectedBankId(e.target.value)}
            >
              <option value="">Cash Account</option>
              {banks.map(b => (
                <option key={b.id} value={b.id}>{b.bankName} - {b.accountNumber}</option>
              ))}
            </Select>
            <div className="pt-4 flex justify-end gap-3 border-t-2 border-[var(--border)]">
              <Button type="button" variant="ghost" onClick={() => setIsSettleModalOpen(false)}>CANCEL</Button>
              <Button type="submit" variant="primary" disabled={isSubmitting}>PAY NOW</Button>
            </div>
          </form>
        </Modal>

        {/* Add Laborer Modal */}
        <Modal isOpen={isAddModalOpen} onClose={() => setAddModalOpen(false)} title="QUICK ADD LABORER">
          <form onSubmit={handleAddLaborer} className="space-y-6">
            <Input
              label="Name *"
              type="text" required value={newLaborerName} onChange={e => setNewLaborerName(e.target.value)}
              placeholder="Laborer or Gang Name"
            />
            <Select
              label="Type *"
              value={newLaborerType} onChange={e => setNewLaborerType(e.target.value)}
            >
              <option value="HAMALI">Hamali (Loading/Unloading)</option>
              <option value="DRIVER">Driver</option>
              <option value="OPERATOR">Machine Operator</option>
              <option value="GENERAL">General Laborer</option>
            </Select>
            <Input
              label="Contact (Optional)"
              type="text" value={newLaborerContact} onChange={e => setNewLaborerContact(e.target.value)}
              placeholder="Phone Number"
            />

            <div className="pt-4 flex justify-end gap-3 border-t-2 border-[var(--border)]">
              <Button type="button" variant="ghost" onClick={() => setAddModalOpen(false)}>CANCEL</Button>
              <Button type="submit" variant="primary" disabled={isAddingLaborer}>
                {isAddingLaborer ? 'ADDING...' : 'ADD LABORER'}
              </Button>
            </div>
          </form>
        </Modal>
      </div>
    </>
  );
}

'use client';

import { useState, useMemo } from 'react';
import { useRouter } from 'next/navigation';
import { toast } from 'sonner';
import { ShoppingCart, Plus, Trash2, User, Phone, MapPin, FileText, Wallet, PackageCheck, Info } from 'lucide-react';
import { finalizeInvoiceAction } from '@/app/actions/sales';
import QuickAddModal, { type EntityType } from './QuickAddModal';
import { Input, Select } from '@/components/ui/Input';
import { Button } from '@/components/ui/Button';
import { Badge } from '@/components/ui/Badge';
import { motion, AnimatePresence } from 'framer-motion';

type Product = { id: string; name: string; category?: string; gstRate: number | string | { toString(): string } };
type Godown = { id: string; name: string };
type Lot = { id: string; productId: string; godownId: string; currentQuantity: number | string | { toString(): string } };
type Customer = { 
  id: string; 
  name: string; 
  contact?: string | null; 
  gstin?: string | null; 
  address?: string | null; 
  balance: number | string | { toString(): string };
};
type Vehicle = { id: string; licensePlate: string };
type PackingItem = {
  id: string;
  brandName: string;
  capacityKg: number | string | { toString(): string };
  quantityBags: number | string | { toString(): string };
  perBagRate: number | string | { toString(): string };
  godownId: string;
  godownName: string;
};

type ItemState = {
  productId: string;
  godownId: string;
  packingItemId: string;
  bagCapacityKg: string; // for Paddy bulk workflow (default 75)
  numberOfBags: string;
  quantity: string;
  rate: string;
  productType?: 'rice' | 'paddy';
};

export default function SalesForm({ 
  customers, 
  vehicles,
  products,
  godowns,
  lots,
  packingItems = []
}: { 
  customers: Customer[],
  vehicles: Vehicle[],
  products: Product[],
  godowns: Godown[],
  lots: Lot[],
  packingItems?: PackingItem[]
}) {
  const router = useRouter();
  const [localCustomers, setLocalCustomers] = useState(customers);
  const [localVehicles, setLocalVehicles] = useState(vehicles);
  const [localProducts, setLocalProducts] = useState(products);
  const [localGodowns, setLocalGodowns] = useState(godowns);

  const [modalOpen, setModalOpen] = useState(false);
  const [modalEntity, setModalEntity] = useState<EntityType>('CUSTOMER');

  const [customerId, setCustomerId] = useState('');
  const [vehicleId, setVehicleId] = useState('');

  // Find default Rice Godown if available
  const defaultRiceGodown = useMemo(() => {
    return localGodowns.find(g => {
      const name = g.name.toLowerCase();
      return name.includes('rice') || name.includes('central');
    }) || localGodowns[0];
  }, [localGodowns]);

  const [items, setItems] = useState<ItemState[]>([]);
  const [generateBill, setGenerateBill] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [mobileStep, setMobileStep] = useState<1 | 2 | 3>(1);

  // Selected Customer object
  const selectedCustomer = useMemo(() => {
    return localCustomers.find(c => c.id === customerId);
  }, [customerId, localCustomers]);

  const addItem = () => {
    const defaultGodownId = defaultRiceGodown ? defaultRiceGodown.id : '';
    const defaultGodownName = (defaultRiceGodown?.name || '').toLowerCase();
    const isPaddyDefault = !defaultGodownName.includes('rice');

    setItems([...items, { 
      productId: '', 
      godownId: defaultGodownId, 
      packingItemId: '', 
      bagCapacityKg: '75', 
      numberOfBags: '', 
      quantity: '', 
      rate: '',
      productType: isPaddyDefault ? 'paddy' : 'rice'
    }]);
  };

  const updateItem = (index: number, field: keyof ItemState, value: string) => {
    const newItems = [...items];
    const item = { ...newItems[index], [field]: value };

    // Reset product & packing if godown changes
    if (field === 'godownId') {
      item.productId = '';
      item.packingItemId = '';
    }

    const selectedGodown = localGodowns.find(g => g.id === item.godownId);
    const godownName = (selectedGodown?.name || '').toLowerCase();

    // RULE: ONLY Godowns with "rice" in their name are Rice Godowns; ALL OTHER GODOWNS ARE PADDY GODOWNS!
    const isRiceGodown = godownName.includes('rice');
    const isPaddy = !isRiceGodown;
    item.productType = isPaddy ? 'paddy' : 'rice';

    if (isPaddy) {
      // Paddy Bulk Sale: Total Weight = NO. OF BAGS * BAG CAPACITY (KG)
      item.packingItemId = '';
      const cap = parseFloat(item.bagCapacityKg) || 75;
      const bagCount = parseFloat(field === 'numberOfBags' ? value : item.numberOfBags) || 0;
      if (cap > 0 && bagCount > 0) {
        item.quantity = (cap * bagCount).toString();
      }
    } else {
      // Rice Packaged Sale: Total Weight = NO. OF BAGS * [Weight of Selected Brand Bag]
      const selectedBag = packingItems.find(p => p.id === (field === 'packingItemId' ? value : item.packingItemId));
      const bagCount = parseFloat(field === 'numberOfBags' ? value : item.numberOfBags) || 0;

      if (selectedBag && bagCount > 0) {
        const bagCap = parseFloat(String(selectedBag.capacityKg)) || 0;
        item.quantity = (bagCount * bagCap).toString();
      }
    }

    newItems[index] = item;
    setItems(newItems);
  };

  const removeItem = (index: number) => {
    setItems(items.filter((_, i) => i !== index));
  };

  const adjustBags = (index: number, amount: number) => {
    const item = items[index];
    const current = parseFloat(item.numberOfBags) || 0;
    const newCount = Math.max(0, current + amount);
    updateItem(index, 'numberOfBags', newCount.toString());
  };

  // Real-time invoice calculations: Line Total = Number of Bags × Rate per Bag
  const invoiceTotals = useMemo(() => {
    let subtotal = 0;
    let taxTotal = 0;

    items.forEach(item => {
      const p = localProducts.find(prod => prod.id === item.productId);
      const bags = parseFloat(item.numberOfBags) || 0;
      const ratePerBag = parseFloat(item.rate) || 0;
      const gst = p && generateBill ? parseFloat(String(p.gstRate)) || 0 : 0;

      const lineTotal = bags * ratePerBag;
      const tax = lineTotal * (gst / 100);

      subtotal += lineTotal;
      taxTotal += tax;
    });

    return { subtotal, taxTotal, grandTotal: subtotal + taxTotal };
  }, [items, localProducts, generateBill]);

  const handleAddSuccess = (newItem: { id: string; name: string; licensePlate?: string }) => {
    setModalOpen(false);
    if (modalEntity === 'CUSTOMER') {
      const newCust: Customer = {
        id: newItem.id,
        name: newItem.name,
        balance: 0,
      };
      setLocalCustomers([...localCustomers, newCust]);
      setCustomerId(newItem.id);
    } else if (modalEntity === 'VEHICLE') {
      const newVeh: Vehicle = {
        id: newItem.id,
        licensePlate: newItem.licensePlate || newItem.name,
      };
      setLocalVehicles([...localVehicles, newVeh]);
      setVehicleId(newItem.id);
    } else if (modalEntity === 'PRODUCT') {
      const newProd: Product = {
        id: newItem.id,
        name: newItem.name,
        gstRate: 0,
      };
      setLocalProducts([...localProducts, newProd]);
    } else if (modalEntity === 'GODOWN') {
      const newGodown: Godown = {
        id: newItem.id,
        name: newItem.name,
      };
      setLocalGodowns([...localGodowns, newGodown]);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (items.length === 0) {
      toast.error("Please add at least one line item.");
      return;
    }

    // Validate packing bag stock and mandatory fields
    for (let i = 0; i < items.length; i++) {
      const item = items[i];
      if (!item.godownId) {
        toast.error(`Item #${i + 1}: Please select a Dispatch Godown.`);
        return;
      }
      if (!item.productId) {
        toast.error(`Item #${i + 1}: Please select a Product / Variety.`);
        return;
      }

      const selectedGodown = localGodowns.find(g => g.id === item.godownId);
      const godownName = (selectedGodown?.name || '').toLowerCase();
      const isRiceGodown = godownName.includes('rice');
      const isPaddy = !isRiceGodown;

      if (!isPaddy && !item.packingItemId) {
        toast.error(`Item #${i + 1}: Please select a Packing Brand Bag for Rice dispatch.`);
        return;
      }
      if (!item.numberOfBags || parseFloat(item.numberOfBags) <= 0) {
        toast.error(`Item #${i + 1}: Please enter a valid number of bags.`);
        return;
      }
      if (!item.rate || parseFloat(item.rate) <= 0) {
        toast.error(`Item #${i + 1}: Please enter a valid rate per bag.`);
        return;
      }

      if (!isPaddy && item.packingItemId) {
        const bag = packingItems.find(p => p.id === item.packingItemId);
        const reqBags = parseFloat(item.numberOfBags) || 0;
        const availBags = bag ? parseFloat(String(bag.quantityBags)) || 0 : 0;
        if (reqBags > availBags) {
          toast.error(`Item #${i + 1}: Requested ${reqBags} bags of "${bag?.brandName}", but only ${availBags} bags are available in stock.`);
          return;
        }
      }
    }

    setIsSubmitting(true);
    try {
      const sanitizedItems = items.map(item => ({
        ...item,
        packingItemId: item.packingItemId ? item.packingItemId : undefined,
        bagCapacityKg: item.bagCapacityKg ? item.bagCapacityKg : '75'
      }));

      const result = await finalizeInvoiceAction({
        customerId,
        vehicleId: vehicleId || undefined,
        items: sanitizedItems,
        generateBill
      });
      toast.success('Invoice Finalized & Inventory Dispatched Successfully!');

      // Auto-redirect to printable invoice page
      router.push(`/invoice/${result.id}`);

    } catch (error) {
      toast.error('Error finalizing invoice: ' + (error instanceof Error ? error.message : String(error)));
      setIsSubmitting(false);
    }
  };

  return (
    <div className="max-w-6xl mx-auto mt-4">

      {/* Mobile Step Progress Bar */}
      <div className="sm:hidden mb-4 px-1">
        <div className="flex items-center gap-0">
          {[
            { step: 1, label: 'Customer' },
            { step: 2, label: 'Items' },
            { step: 3, label: 'Review' }
          ].map((s, i) => (
            <div key={s.step} className="flex items-center flex-1">
              <button type="button" onClick={() => setMobileStep(s.step as 1|2|3)}
                className="flex flex-col items-center gap-1 flex-1">
                <div className={`w-8 h-8 rounded-full flex items-center justify-center font-black text-sm border-2 transition-all ${mobileStep >= s.step ? 'bg-[#F5A623] border-[#F5A623] text-black' : 'bg-[#1A1A1A] border-neutral-700 text-neutral-500'}`}>
                  {s.step}
                </div>
                <span className={`text-[9px] font-black uppercase tracking-wider ${mobileStep >= s.step ? 'text-[#F5A623]' : 'text-neutral-600'}`}>{s.label}</span>
              </button>
              {i < 2 && <div className={`h-0.5 flex-1 mx-1 rounded transition-all ${mobileStep > s.step ? 'bg-[#F5A623]' : 'bg-neutral-800'}`} />}
            </div>
          ))}
        </div>
      </div>

      <div className="bg-[#111111] rounded-3xl border border-neutral-800 overflow-hidden shadow-2xl">

        {/* Header */}
        <div className="bg-gradient-to-r from-[#0E0E0E] to-[#1a1400] px-5 py-5 sm:px-8 sm:py-7 border-b border-neutral-800 flex items-start justify-between gap-4">
          <div>
            <h2 className="font-black text-xl sm:text-3xl text-white flex items-center gap-3 tracking-tight">
              <div className="p-2 bg-[#F5A623]/20 rounded-xl">
                <ShoppingCart className="h-5 w-5 sm:h-7 sm:w-7 text-[#F5A623]" />
              </div>
              Sales & Dispatch
            </h2>
            <p className="text-neutral-500 text-xs sm:text-sm font-medium mt-1.5 ml-1">Select customer · Add items · Generate invoice</p>
          </div>
          {/* Running total badge on mobile */}
          {invoiceTotals.grandTotal > 0 && (
            <div className="shrink-0 bg-[#F5A623]/20 border border-[#F5A623]/40 rounded-2xl px-3 py-2 text-right">
              <p className="text-[9px] font-black uppercase text-[#F5A623]/70">Total</p>
              <p className="font-mono font-black text-[#F5A623] text-base">₹{invoiceTotals.grandTotal.toLocaleString('en-IN', {maximumFractionDigits: 0})}</p>
            </div>
          )}
        </div>

        <form className="p-5 sm:p-8 space-y-6" onSubmit={handleSubmit}>

          {/* ===== STEP 1: CUSTOMER ===== */}
          <div className={`space-y-5 ${mobileStep === 1 ? 'block' : 'hidden sm:block'}`}>
            <h3 className="text-[10px] font-black uppercase tracking-widest text-neutral-500 flex items-center gap-2">
              <User className="w-3.5 h-3.5" /> Step 1 — Customer & Vehicle
            </h3>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="flex gap-2 items-end">
                <Select label="Select Customer *" value={customerId} onChange={e => setCustomerId(e.target.value)} required>
                  <option value="">Select Customer...</option>
                  {localCustomers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </Select>
                <Button type="button" variant="ghost" onClick={() => { setModalEntity('CUSTOMER'); setModalOpen(true); }} className="px-3 mb-[2px]">
                  <Plus className="w-5 h-5" />
                </Button>
              </div>
              <div className="flex gap-2 items-end">
                <Select label="Dispatch Vehicle (Optional)" value={vehicleId} onChange={e => setVehicleId(e.target.value)}>
                  <option value="">No vehicle / Customer Transport...</option>
                  {localVehicles.map(v => <option key={v.id} value={v.id}>{v.licensePlate}</option>)}
                </Select>
                <Button type="button" variant="ghost" onClick={() => { setModalEntity('VEHICLE'); setModalOpen(true); }} className="px-3 mb-[2px]">
                  <Plus className="w-5 h-5" />
                </Button>
              </div>
            </div>

            {/* Customer Info Card */}
            <AnimatePresence>
              {selectedCustomer && (
                <motion.div initial={{ opacity: 0, y: -8 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -8 }}
                  className="bg-[#1A1A1A] rounded-2xl border border-neutral-800 p-4 sm:p-5">
                  <div className="flex items-center gap-3 mb-4">
                    <div className="w-10 h-10 rounded-xl bg-[#F5A623]/20 flex items-center justify-center font-black text-[#F5A623] text-lg">
                      {selectedCustomer.name.charAt(0).toUpperCase()}
                    </div>
                    <div>
                      <p className="font-black text-white text-base">{selectedCustomer.name}</p>
                      {selectedCustomer.gstin && <p className="text-[10px] font-black uppercase text-neutral-500">GSTIN: {selectedCustomer.gstin}</p>}
                    </div>
                    <div className="ml-auto text-right">
                      <p className="text-[10px] font-black uppercase text-neutral-500">Balance</p>
                      <p className={`font-mono font-black text-lg tabular-nums ${Number(selectedCustomer.balance) > 0 ? 'text-red-400' : 'text-emerald-400'}`}>
                        ₹{Number(selectedCustomer.balance).toLocaleString('en-IN', { minimumFractionDigits: 0 })}
                      </p>
                    </div>
                  </div>
                  <div className="grid grid-cols-2 gap-3 text-xs border-t border-neutral-800 pt-3">
                    {selectedCustomer.contact && (
                      <div className="flex items-center gap-1.5 text-neutral-400">
                        <Phone className="w-3 h-3" />
                        <span className="font-semibold">{selectedCustomer.contact}</span>
                      </div>
                    )}
                    {selectedCustomer.address && (
                      <div className="flex items-center gap-1.5 text-neutral-400">
                        <MapPin className="w-3 h-3" />
                        <span className="font-semibold truncate">{selectedCustomer.address}</span>
                      </div>
                    )}
                  </div>
                </motion.div>
              )}
            </AnimatePresence>

            <div className="sm:hidden">
              <button type="button" onClick={() => setMobileStep(2)}
                className="w-full py-4 bg-[#F5A623] text-black font-black uppercase tracking-wider rounded-2xl active:scale-95 transition-transform text-base">
                Next: Add Items →
              </button>
            </div>
          </div>

          {/* ===== STEP 2: ITEMS ===== */}
          <div className={`space-y-4 ${mobileStep === 2 ? 'block' : 'hidden sm:block'} sm:pt-6 sm:border-t sm:border-neutral-800`}>
            <div className="flex items-center justify-between">
              <h3 className="text-[10px] font-black uppercase tracking-widest text-neutral-500 flex items-center gap-2">
                <PackageCheck className="w-3.5 h-3.5" /> Step 2 — Dispatch Items
              </h3>
              <button type="button" onClick={addItem}
                className="flex items-center gap-1.5 px-3 py-2 bg-[#1A1A1A] border border-neutral-700 rounded-xl text-[#F5A623] font-black text-xs uppercase tracking-wider hover:border-[#F5A623] transition-colors">
                <Plus className="w-3.5 h-3.5" /> Add Item
              </button>
            </div>

            {items.length === 0 ? (
              <div className="py-12 text-center bg-[#1A1A1A] rounded-2xl border border-dashed border-neutral-700">
                <PackageCheck className="w-10 h-10 text-neutral-700 mx-auto mb-3" />
                <p className="text-neutral-500 font-black uppercase text-sm">No items yet</p>
                <p className="text-neutral-600 text-xs mt-1">Tap &quot;Add Item&quot; to add dispatch items</p>
              </div>
            ) : (
              <div className="space-y-4">
                <AnimatePresence>
                  {items.map((item, index) => {
                    const g = localGodowns.find(godown => godown.id === item.godownId);
                    const godownName = (g?.name || '').toLowerCase();
                    const isRiceGodown = godownName.includes('rice');
                    const isPaddy = !isRiceGodown;
                    const bags = parseFloat(item.numberOfBags) || 0;
                    const ratePerBag = parseFloat(item.rate) || 0;
                    const lineTotal = bags * ratePerBag;
                    const availableProductsForGodown = (() => {
                      if (!item.godownId) return localProducts;
                      const godownLots = lots.filter(l => l.godownId === item.godownId && Number(l.currentQuantity) > 0);
                      const activeProductIds = Array.from(new Set(godownLots.map(l => l.productId)));
                      const filtered = localProducts.filter(prod => activeProductIds.includes(prod.id));
                      return filtered.length > 0 ? filtered : localProducts;
                    })();

                    return (
                      <motion.div key={index}
                        initial={{ opacity: 0, x: -16 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, scale: 0.95 }}
                        className="bg-[#1A1A1A] rounded-2xl border border-neutral-800 overflow-hidden">

                        {/* Item header */}
                        <div className="flex items-center justify-between px-4 py-3 border-b border-neutral-800">
                          <div className="flex items-center gap-2">
                            <span className="text-[10px] font-black uppercase px-2 py-0.5 bg-[#F5A623]/20 text-[#F5A623] rounded-lg border border-[#F5A623]/30">
                              #{index + 1}
                            </span>
                            <span className={`text-[10px] font-black uppercase px-2 py-0.5 rounded-lg border ${isPaddy ? 'bg-amber-950/50 text-amber-400 border-amber-900/40' : 'bg-emerald-950/50 text-emerald-400 border-emerald-900/40'}`}>
                              {isPaddy ? '🌾 Paddy' : '🍚 Rice'}
                            </span>
                          </div>
                          <button type="button" onClick={() => removeItem(index)}
                            className="p-1.5 bg-red-950/50 border border-red-900/40 rounded-lg text-red-400 hover:bg-red-900/40 transition-colors">
                            <Trash2 className="w-3.5 h-3.5" />
                          </button>
                        </div>

                        <div className="p-4 space-y-4">
                          {/* Godown + Product row */}
                          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                            <div className="flex gap-2 items-end">
                              <Select label="DISPATCH GODOWN *" required value={item.godownId}
                                onChange={e => updateItem(index, 'godownId', e.target.value)}>
                                <option value="">Select Godown...</option>
                                {localGodowns
                                  .filter(god => !god.name.toLowerCase().includes('common') && !god.name.toLowerCase().includes('packaging'))
                                  .map(god => (
                                    <option key={god.id} value={god.id}>
                                      {god.name} {god.name.toLowerCase().includes('rice') ? '(Rice)' : '(Paddy)'}
                                    </option>
                                  ))}
                              </Select>
                              <Button type="button" variant="ghost" onClick={() => { setModalEntity('GODOWN'); setModalOpen(true); }} className="px-3 mb-[2px]">
                                <Plus className="w-4 h-4" />
                              </Button>
                            </div>

                            <div className="flex gap-2 items-end">
                              <Select label="PRODUCT / VARIETY *" required value={item.productId}
                                onChange={e => { updateItem(index, 'productId', e.target.value); }}
                                disabled={!item.godownId}>
                                {!item.godownId ? (
                                  <option value="">Select Godown First...</option>
                                ) : (
                                  <>
                                    <option value="">Select Variety...</option>
                                    {availableProductsForGodown.map(prod => {
                                      const availStock = lots.filter(l => l.godownId === item.godownId && l.productId === prod.id).reduce((sum, l) => sum + Number(String(l.currentQuantity)), 0);
                                      return <option key={prod.id} value={prod.id}>{prod.name} ({availStock.toLocaleString('en-IN')} kg)</option>;
                                    })}
                                  </>
                                )}
                              </Select>
                              <Button type="button" variant="ghost" onClick={() => { setModalEntity('PRODUCT'); setModalOpen(true); }} className="px-3 mb-[2px]">
                                <Plus className="w-4 h-4" />
                              </Button>
                            </div>
                          </div>

                          {/* Paddy bag capacity or Rice packing brand */}
                          {isPaddy ? (
                            <div className="bg-amber-950/30 border border-amber-900/40 rounded-xl p-3 flex flex-col sm:flex-row gap-3 items-center">
                              <div className="flex-1 w-full">
                                <label className="text-[10px] font-black text-amber-400 uppercase tracking-wider block mb-1">
                                  BAG CAPACITY (KG) *
                                </label>
                                <input type="number" step="0.1" value={item.bagCapacityKg || '75'}
                                  onChange={e => updateItem(index, 'bagCapacityKg', e.target.value)}
                                  placeholder="e.g. 75"
                                  className="w-full bg-[#111] border border-amber-800/50 rounded-lg px-3 py-2.5 font-mono font-bold text-white focus:outline-none focus:border-amber-500" />
                              </div>
                              <div className="flex items-center text-[10px] text-amber-400/80 font-bold gap-1.5 sm:pt-5">
                                <Info className="w-3.5 h-3.5 shrink-0" />
                                <span>Plain gunny bags @ {item.bagCapacityKg || '75'} kg each</span>
                              </div>
                            </div>
                          ) : (
                            <Select label="PACKING BRAND BAG *" required value={item.packingItemId}
                              onChange={e => updateItem(index, 'packingItemId', e.target.value)}>
                              <option value="">Select Packing Bag...</option>
                              {packingItems.map(pkg => (
                                <option key={pkg.id} value={pkg.id}>
                                  {pkg.brandName} ({String(pkg.capacityKg)}kg — {String(pkg.quantityBags)} bags in stock)
                                </option>
                              ))}
                            </Select>
                          )}

                          {/* Bags + Rate + Weight + Subtotal */}
                          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 items-end pt-3 border-t border-neutral-800">
                            <div>
                              <label className="text-[10px] font-black uppercase tracking-widest text-neutral-400 block mb-1">Bags *</label>
                              <div className="flex h-[44px]">
                                <button type="button" onClick={() => adjustBags(index, -10)} className="w-10 bg-neutral-800 text-white font-black rounded-l-xl border border-r-0 border-neutral-700 active:bg-red-900 text-xl flex items-center justify-center">-</button>
                                <input type="number" step="1" required value={item.numberOfBags} onChange={e => updateItem(index, 'numberOfBags', e.target.value)} placeholder="0"
                                  className="flex-1 text-center font-mono font-black text-white bg-[#111] border-y border-neutral-700 focus:outline-none focus:border-[#F5A623] min-w-0" />
                                <button type="button" onClick={() => adjustBags(index, 10)} className="w-10 bg-neutral-800 text-white font-black rounded-r-xl border border-l-0 border-neutral-700 active:bg-emerald-900 text-xl flex items-center justify-center">+</button>
                              </div>
                            </div>

                            <div>
                              <label className="text-[10px] font-black uppercase tracking-widest text-neutral-400 block mb-1">Rate ₹/Bag *</label>
                              <input type="number" step="0.01" required value={item.rate} onChange={e => updateItem(index, 'rate', e.target.value)}
                                placeholder="0.00" inputMode="decimal"
                                className="w-full h-[44px] bg-[#111] border border-neutral-700 rounded-xl px-3 font-mono font-bold text-emerald-400 focus:outline-none focus:border-emerald-500 transition-colors" />
                            </div>

                            <div>
                              <label className="text-[10px] font-black uppercase tracking-widest text-neutral-400 block mb-1">Weight (kg)</label>
                              <input type="number" step="0.01" required value={item.quantity} onChange={e => updateItem(index, 'quantity', e.target.value)}
                                placeholder="auto"
                                className="w-full h-[44px] bg-neutral-900 border border-neutral-800 rounded-xl px-3 font-mono font-bold text-neutral-400 focus:outline-none focus:border-neutral-600" />
                            </div>

                            <div className="text-right">
                              <p className="text-[10px] font-black uppercase text-neutral-500 mb-1">Line Total</p>
                              <p className="font-mono font-black text-xl text-[#F5A623] tabular-nums">
                                ₹{lineTotal.toLocaleString('en-IN', { maximumFractionDigits: 0 })}
                              </p>
                            </div>
                          </div>
                        </div>
                      </motion.div>
                    );
                  })}
                </AnimatePresence>
              </div>
            )}

            <div className="sm:hidden flex gap-3 mt-2">
              <button type="button" onClick={() => setMobileStep(1)}
                className="flex-1 py-4 bg-[#1A1A1A] border border-neutral-700 text-neutral-300 font-black uppercase tracking-wider rounded-2xl active:scale-95 transition-transform">
                ← Back
              </button>
              <button type="button" onClick={() => setMobileStep(3)}
                className="flex-1 py-4 bg-[#F5A623] text-black font-black uppercase tracking-wider rounded-2xl active:scale-95 transition-transform">
                Review →
              </button>
            </div>
          </div>

          {/* ===== STEP 3: REVIEW & SUBMIT ===== */}
          <div className={`space-y-5 ${mobileStep === 3 ? 'block' : 'hidden sm:block'} sm:pt-6 sm:border-t sm:border-neutral-800`}>
            <h3 className="text-[10px] font-black uppercase tracking-widest text-neutral-500 flex items-center gap-2">
              <FileText className="w-3.5 h-3.5" /> Step 3 — Review & Submit
            </h3>

            {/* Invoice Summary */}
            <div className="bg-[#1A1A1A] rounded-2xl border border-neutral-800 overflow-hidden">
              <div className="px-5 py-4 border-b border-neutral-800">
                <p className="text-[10px] font-black uppercase tracking-widest text-neutral-500">Invoice Summary</p>
              </div>
              <div className="p-5 space-y-3">
                <div className="flex justify-between text-sm font-bold">
                  <span className="text-neutral-400 uppercase text-xs">Subtotal</span>
                  <span className="font-mono text-white">₹{invoiceTotals.subtotal.toLocaleString('en-IN', { minimumFractionDigits: 2 })}</span>
                </div>
                <div className="flex justify-between text-sm font-bold">
                  <span className="text-neutral-400 uppercase text-xs">GST</span>
                  <span className="font-mono text-neutral-300">₹{invoiceTotals.taxTotal.toLocaleString('en-IN', { minimumFractionDigits: 2 })}</span>
                </div>
                <div className="flex justify-between items-center pt-3 border-t border-neutral-800">
                  <span className="font-black text-white uppercase text-base">Grand Total</span>
                  <span className="font-mono font-black text-2xl text-emerald-400">₹{invoiceTotals.grandTotal.toLocaleString('en-IN', { minimumFractionDigits: 2 })}</span>
                </div>
              </div>
            </div>

            <label className="flex items-center gap-3 cursor-pointer bg-[#1A1A1A] rounded-2xl border border-neutral-800 p-4">
              <input type="checkbox" checked={generateBill} onChange={e => setGenerateBill(e.target.checked)}
                className="w-5 h-5 accent-[#F5A623] cursor-pointer rounded" />
              <div>
                <p className="text-sm font-black text-white">Generate Official Tax Bill</p>
                <p className="text-[10px] text-neutral-500">Includes GST breakdown and bill of supply</p>
              </div>
            </label>

            <div className="flex gap-3">
              <button type="button" onClick={() => setMobileStep(2)}
                className="sm:hidden px-6 py-4 bg-[#1A1A1A] border border-neutral-700 text-neutral-300 font-black rounded-2xl active:scale-95 transition-transform">
                ← Back
              </button>
              <button type="submit" disabled={isSubmitting || items.length === 0}
                className="flex-1 py-4 sm:py-5 bg-[#F5A623] text-black font-black text-base sm:text-xl uppercase tracking-wider rounded-2xl active:scale-95 transition-all disabled:opacity-50 shadow-lg shadow-[#F5A623]/20">
                {isSubmitting ? 'Dispatching & Generating...' : '⚡ Dispatch & Generate Invoice'}
              </button>
            </div>
          </div>

        </form>
      </div>

      <QuickAddModal
        isOpen={modalOpen}
        onClose={() => setModalOpen(false)}
        entityType={modalEntity}
        onSuccess={handleAddSuccess}
      />
    </div>
  );
}

'use client';

import { useState } from 'react';
import { toast } from 'sonner';
import {
  Truck, ShieldAlert, BadgeCheck, FileWarning, Search, Landmark, CreditCard,
  Droplet, UserCog, Edit, Trash2, Plus, AlertTriangle, CheckCircle2, X
} from 'lucide-react';
import { createVehicleAction, updateVehicleAction, deleteVehicleAction } from '@/app/actions/masterData';
import { recordVehicleCommissionAction, logVehicleExpenseAction, settleVehiclePaymentAction, assignDriverAction } from '@/app/actions/vehicles';
import { Input, Select } from '@/components/ui/Input';
import { Button } from '@/components/ui/Button';
import { Modal } from '@/components/ui/Modal';
import { motion, AnimatePresence } from 'framer-motion';

type SerializedVehicle = {
  id: string; licensePlate: string; type: string; tareWeight: number | null;
  ownershipType: string; insuranceExpiry: string | null; fitnessExpiry: string | null;
  pollutionExpiry: string | null; ownerName: string | null; contactNumber: string | null;
  balance: number; assignedDriverId: string | null;
};
type SelectOption = { id: string; name?: string; bankName?: string; accountNumber?: string };

function CompliancePill({ label, expiry }: { label: string; expiry: string | null }) {
  const now = new Date();
  const exp = expiry ? new Date(expiry) : null;
  const diffDays = exp ? Math.ceil((exp.getTime() - now.getTime()) / 86400000) : null;
  const isExpired = exp ? exp < now : false;
  const isSoon = !isExpired && diffDays !== null && diffDays <= 30;

  if (!exp) return null;
  return (
    <div className={`flex items-center gap-1.5 px-2 py-1 rounded-lg text-[10px] font-black uppercase tracking-wider border ${
      isExpired ? 'bg-red-950/50 border-red-900/60 text-red-400' :
      isSoon ? 'bg-amber-950/50 border-amber-900/60 text-amber-400' :
      'bg-emerald-950/40 border-emerald-900/50 text-emerald-400'
    }`}>
      {isExpired ? <ShieldAlert className="w-3 h-3" /> : isSoon ? <FileWarning className="w-3 h-3" /> : <BadgeCheck className="w-3 h-3" />}
      {label}
      {isExpired ? ' EXP' : isSoon ? ` ${diffDays}d` : ' OK'}
    </div>
  );
}

export default function VehicleManagementModule({
  initialVehicles, drivers, banks, expenseCategories, userRole
}: {
  initialVehicles: SerializedVehicle[]; drivers: SelectOption[]; banks: SelectOption[];
  expenseCategories: SelectOption[]; userRole: string;
}) {
  const [activeTab, setActiveTab] = useState<'OWNED' | 'THIRD_PARTY'>('OWNED');
  const [vehicles, setVehicles] = useState(initialVehicles);
  const [searchTerm, setSearchTerm] = useState('');

  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isCommissionModalOpen, setIsCommissionModalOpen] = useState(false);
  const [isExpenseModalOpen, setIsExpenseModalOpen] = useState(false);
  const [isSettleModalOpen, setIsSettleModalOpen] = useState(false);

  const [selectedVehicleId, setSelectedVehicleId] = useState('');
  const [editMode, setEditMode] = useState(false);
  const isAdmin = userRole === 'ADMIN' || userRole === 'MANAGER';

  const [amount, setAmount] = useState('');
  const [description, setDescription] = useState('');
  const [selectedBankId, setSelectedBankId] = useState('');
  const [selectedCategoryId, setSelectedCategoryId] = useState('');

  const [formLicensePlate, setFormLicensePlate] = useState('');
  const [formType, setFormType] = useState('TRUCK');
  const [formTareWeight, setFormTareWeight] = useState('');
  const [formInsurance, setFormInsurance] = useState('');
  const [formFitness, setFormFitness] = useState('');
  const [formPollution, setFormPollution] = useState('');
  const [formOwnerName, setFormOwnerName] = useState('');
  const [formContact, setFormContact] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const filteredVehicles = vehicles
    .filter(v => v.ownershipType === activeTab)
    .filter(v => v.licensePlate.toLowerCase().includes(searchTerm.toLowerCase()));

  const ownedCount = vehicles.filter(v => v.ownershipType === 'OWNED').length;
  const thirdPartyCount = vehicles.filter(v => v.ownershipType === 'THIRD_PARTY').length;

  const handleAddSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    try {
      const fd = new FormData();
      fd.append('licensePlate', formLicensePlate);
      fd.append('type', formType);
      fd.append('ownershipType', activeTab);
      if (formTareWeight) fd.append('tareWeight', formTareWeight);
      if (activeTab === 'OWNED') {
        if (formInsurance) fd.append('insuranceExpiry', formInsurance);
        if (formFitness) fd.append('fitnessExpiry', formFitness);
        if (formPollution) fd.append('pollutionExpiry', formPollution);
      } else {
        if (formOwnerName) fd.append('ownerName', formOwnerName);
        if (formContact) fd.append('contactNumber', formContact);
      }
      if (editMode && selectedVehicleId) {
        fd.append('id', selectedVehicleId);
        await updateVehicleAction(fd);
        toast.success('Vehicle updated!');
      } else {
        await createVehicleAction(fd);
        toast.success('Vehicle registered!');
      }
      window.location.reload();
    } catch (error) {
      toast.error('Failed: ' + (error instanceof Error ? error.message : String(error)));
      setIsSubmitting(false);
    }
  };

  const handleCommissionSubmit = async (e: React.FormEvent) => {
    e.preventDefault(); setIsSubmitting(true);
    try {
      const fd = new FormData();
      fd.append('vehicleId', selectedVehicleId); fd.append('amount', amount); fd.append('description', description);
      await recordVehicleCommissionAction(fd);
      toast.success('Freight commission recorded!'); window.location.reload();
    } catch (error) { toast.error('Failed: ' + (error instanceof Error ? error.message : String(error))); setIsSubmitting(false); }
  };

  const handleExpenseSubmit = async (e: React.FormEvent) => {
    e.preventDefault(); setIsSubmitting(true);
    try {
      const fd = new FormData();
      fd.append('vehicleId', selectedVehicleId); fd.append('categoryId', selectedCategoryId);
      fd.append('amount', amount); fd.append('description', description);
      if (selectedBankId) fd.append('bankId', selectedBankId);
      await logVehicleExpenseAction(fd);
      toast.success('Expense logged!'); window.location.reload();
    } catch (error) { toast.error('Failed: ' + (error instanceof Error ? error.message : String(error))); setIsSubmitting(false); }
  };

  const handleSettleSubmit = async (e: React.FormEvent) => {
    e.preventDefault(); setIsSubmitting(true);
    try {
      const fd = new FormData();
      fd.append('vehicleId', selectedVehicleId); fd.append('amount', amount);
      if (selectedBankId) fd.append('bankId', selectedBankId);
      await settleVehiclePaymentAction(fd);
      toast.success('Payment settled!'); window.location.reload();
    } catch (error) { toast.error('Failed: ' + (error instanceof Error ? error.message : String(error))); setIsSubmitting(false); }
  };

  const handleAssignDriver = async (vehicleId: string, driverId: string) => {
    try {
      const fd = new FormData();
      fd.append('vehicleId', vehicleId); fd.append('driverId', driverId);
      await assignDriverAction(fd);
      toast.success('Driver assigned!');
    } catch { toast.error('Failed to assign driver'); }
  };

  const handleEditClick = (v: SerializedVehicle) => {
    setEditMode(true); setSelectedVehicleId(v.id);
    setFormLicensePlate(v.licensePlate); setFormType(v.type);
    setFormTareWeight(v.tareWeight ? v.tareWeight.toString() : '');
    setFormInsurance(v.insuranceExpiry ? v.insuranceExpiry.split('T')[0] : '');
    setFormFitness(v.fitnessExpiry ? v.fitnessExpiry.split('T')[0] : '');
    setFormPollution(v.pollutionExpiry ? v.pollutionExpiry.split('T')[0] : '');
    setFormOwnerName(v.ownerName || ''); setFormContact(v.contactNumber || '');
    setIsAddModalOpen(true);
  };

  const handleDeleteClick = async (id: string) => {
    if (confirm('Delete this vehicle? This will remove associated records.')) {
      try {
        const fd = new FormData(); fd.append('id', id);
        await deleteVehicleAction(fd); window.location.reload();
      } catch { toast.error('Failed to delete vehicle'); }
    }
  };

  return (
    <div className="max-w-7xl mx-auto mt-4 space-y-6">

      {/* Tab Toggle */}
      <div className="flex bg-[#1A1A1A] p-1.5 rounded-2xl border border-neutral-800 shadow-xl">
        {[
          { id: 'OWNED', label: 'Business Fleet', color: 'bg-emerald-500', count: ownedCount },
          { id: 'THIRD_PARTY', label: 'Third-Party', color: 'bg-[#F5A623]', count: thirdPartyCount },
        ].map(tab => (
          <button key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`flex-1 py-3 rounded-xl font-black uppercase tracking-wider text-xs sm:text-sm transition-all flex items-center justify-center gap-2 ${activeTab === tab.id ? `${tab.color} text-white shadow-lg` : 'text-neutral-500 hover:text-neutral-300'}`}>
            <Truck className="w-4 h-4" />
            <span>{tab.label}</span>
            <span className={`px-2 py-0.5 rounded-full text-xs font-black ${activeTab === tab.id ? 'bg-white/20' : 'bg-neutral-800'}`}>{tab.count}</span>
          </button>
        ))}
      </div>

      {/* Search + Register Row */}
      <div className="flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-neutral-500" />
          <input type="text" placeholder="Search plate number..."
            value={searchTerm} onChange={e => setSearchTerm(e.target.value)}
            className="w-full pl-11 pr-4 py-3.5 bg-[#1A1A1A] border border-neutral-800 rounded-2xl text-white font-semibold text-sm placeholder:text-neutral-600 focus:outline-none focus:border-[#F5A623] transition-colors" />
          {searchTerm && (
            <button onClick={() => setSearchTerm('')} className="absolute right-3 top-1/2 -translate-y-1/2 p-1 bg-neutral-700 rounded-full">
              <X className="w-3 h-3 text-neutral-300" />
            </button>
          )}
        </div>
        <button
          onClick={() => { setEditMode(false); setIsAddModalOpen(true); setFormLicensePlate(''); setFormType('TRUCK'); setFormTareWeight(''); setFormInsurance(''); setFormFitness(''); setFormPollution(''); setFormOwnerName(''); setFormContact(''); }}
          className={`flex items-center justify-center gap-2 px-5 py-3.5 rounded-2xl font-black uppercase tracking-wider text-sm transition-all active:scale-95 shadow-lg w-full sm:w-auto ${activeTab === 'OWNED' ? 'bg-emerald-500 text-white shadow-emerald-500/30' : 'bg-[#F5A623] text-black shadow-[#F5A623]/30'}`}>
          <Plus className="w-5 h-5" />
          Register {activeTab === 'OWNED' ? 'Fleet' : 'Third-Party'}
        </button>
      </div>

      {/* Vehicle Cards Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
        <AnimatePresence>
          {filteredVehicles.map((v, i) => {
            const hasCompliance = v.ownershipType === 'OWNED';
            const isAnyExpired = hasCompliance && (
              (v.insuranceExpiry && new Date(v.insuranceExpiry) < new Date()) ||
              (v.fitnessExpiry && new Date(v.fitnessExpiry) < new Date()) ||
              (v.pollutionExpiry && new Date(v.pollutionExpiry) < new Date())
            );

            return (
              <motion.div key={v.id}
                initial={{ opacity: 0, scale: 0.97 }} animate={{ opacity: 1, scale: 1 }}
                exit={{ opacity: 0, scale: 0.95 }} transition={{ delay: i * 0.04 }}
                className={`bg-[#1A1A1A] rounded-2xl border flex flex-col overflow-hidden transition-colors ${isAnyExpired ? 'border-red-900/60' : 'border-neutral-800 hover:border-neutral-700'}`}>

                {/* Card Header */}
                <div className="p-4 flex items-start justify-between gap-3">
                  <div className="flex items-start gap-3 flex-1 min-w-0">
                    {/* Vehicle Icon */}
                    <div className={`p-2.5 rounded-xl shrink-0 ${activeTab === 'OWNED' ? 'bg-emerald-500/20' : 'bg-[#F5A623]/20'}`}>
                      <Truck className={`w-5 h-5 ${activeTab === 'OWNED' ? 'text-emerald-400' : 'text-[#F5A623]'}`} />
                    </div>
                    <div className="flex-1 min-w-0">
                      <h3 className="font-mono font-black text-xl text-white uppercase tracking-tighter truncate">{v.licensePlate}</h3>
                      <div className="flex items-center gap-2 mt-1 flex-wrap">
                        <span className="text-[10px] font-black uppercase px-2 py-0.5 bg-neutral-800 text-neutral-400 rounded-lg border border-neutral-700">{v.type}</span>
                        {v.tareWeight && <span className="text-[10px] font-black uppercase px-2 py-0.5 bg-neutral-800 text-neutral-400 rounded-lg border border-neutral-700">{v.tareWeight} MT</span>}
                      </div>
                    </div>
                  </div>
                  {isAnyExpired && (
                    <div className="shrink-0 p-1.5 bg-red-950/60 border border-red-900/60 rounded-xl">
                      <AlertTriangle className="w-4 h-4 text-red-400" />
                    </div>
                  )}
                </div>

                {/* Compliance Pills (OWNED only) */}
                {activeTab === 'OWNED' && (
                  <div className="px-4 pb-3 flex flex-wrap gap-1.5">
                    <CompliancePill label="Ins" expiry={v.insuranceExpiry} />
                    <CompliancePill label="Fit" expiry={v.fitnessExpiry} />
                    <CompliancePill label="PUC" expiry={v.pollutionExpiry} />
                  </div>
                )}

                {/* Third-Party Info */}
                {activeTab === 'THIRD_PARTY' && (
                  <div className="px-4 pb-3 space-y-1">
                    <div className="flex justify-between text-xs">
                      <span className="text-neutral-500 font-black uppercase">Owner</span>
                      <span className="text-neutral-300 font-semibold">{v.ownerName || 'Unknown'}</span>
                    </div>
                    {v.contactNumber && (
                      <div className="flex justify-between text-xs">
                        <span className="text-neutral-500 font-black uppercase">Contact</span>
                        <span className="text-neutral-300 font-semibold">{v.contactNumber}</span>
                      </div>
                    )}
                    <div className="flex justify-between items-center pt-2 border-t border-neutral-800">
                      <span className="text-neutral-500 font-black uppercase text-xs">Commission Due</span>
                      <span className={`font-mono font-black text-lg tabular-nums ${v.balance > 0 ? 'text-[#F5A623]' : 'text-neutral-400'}`}>₹{v.balance.toFixed(2)}</span>
                    </div>
                  </div>
                )}

                {/* Owned: Driver Assignment */}
                {activeTab === 'OWNED' && (
                  <div className="px-4 pb-3 border-t border-neutral-800 pt-3">
                    <label className="text-[10px] font-black uppercase tracking-widest text-neutral-500 flex items-center gap-1 mb-1.5">
                      <UserCog className="w-3 h-3" /> Driver
                    </label>
                    <select value={v.assignedDriverId || ''}
                      onChange={e => handleAssignDriver(v.id, e.target.value)}
                      className="w-full text-sm font-bold py-2 px-3 bg-[#111] border border-neutral-800 rounded-xl text-white focus:outline-none focus:border-emerald-500 transition-colors">
                      <option value="">Unassigned</option>
                      {drivers.map(d => <option key={d.id} value={d.id}>{d.name}</option>)}
                    </select>
                  </div>
                )}

                {/* Action Buttons Row */}
                <div className="mt-auto border-t border-neutral-800 flex overflow-x-auto hide-scrollbar">
                  {activeTab === 'THIRD_PARTY' && (
                    <>
                      <button onClick={() => { setSelectedVehicleId(v.id); setAmount(''); setDescription(''); setIsCommissionModalOpen(true); }}
                        className="flex-1 py-3 flex flex-col items-center gap-1 text-[9px] font-black uppercase text-[#F5A623] hover:bg-[#F5A623]/10 transition-colors border-r border-neutral-800 min-w-[64px]">
                        <Landmark className="w-4 h-4" />
                        Freight
                      </button>
                      <button onClick={() => { setSelectedVehicleId(v.id); setAmount(''); setIsSettleModalOpen(true); }}
                        className="flex-1 py-3 flex flex-col items-center gap-1 text-[9px] font-black uppercase text-emerald-400 hover:bg-emerald-500/10 transition-colors border-r border-neutral-800 min-w-[64px]">
                        <CreditCard className="w-4 h-4" />
                        Settle
                      </button>
                    </>
                  )}
                  {activeTab === 'OWNED' && (
                    <button onClick={() => { setSelectedVehicleId(v.id); setAmount(''); setDescription(''); setIsExpenseModalOpen(true); }}
                      className="flex-1 py-3 flex flex-col items-center gap-1 text-[9px] font-black uppercase text-sky-400 hover:bg-sky-500/10 transition-colors border-r border-neutral-800 min-w-[64px]">
                      <Droplet className="w-4 h-4" />
                      Expense
                    </button>
                  )}
                  {isAdmin && (
                    <>
                      <button onClick={() => handleEditClick(v)}
                        className="flex-1 py-3 flex flex-col items-center gap-1 text-[9px] font-black uppercase text-neutral-400 hover:bg-neutral-800 transition-colors border-r border-neutral-800 min-w-[64px]">
                        <Edit className="w-4 h-4" />
                        Edit
                      </button>
                      <button onClick={() => handleDeleteClick(v.id)}
                        className="flex-1 py-3 flex flex-col items-center gap-1 text-[9px] font-black uppercase text-red-400 hover:bg-red-500/10 transition-colors min-w-[64px]">
                        <Trash2 className="w-4 h-4" />
                        Delete
                      </button>
                    </>
                  )}
                </div>
              </motion.div>
            );
          })}
        </AnimatePresence>

        {filteredVehicles.length === 0 && (
          <div className="col-span-full py-20 text-center">
            <Truck className="w-12 h-12 text-neutral-700 mx-auto mb-4" />
            <p className="text-neutral-500 font-black uppercase tracking-widest text-sm">No vehicles found.</p>
            <p className="text-neutral-600 text-xs mt-1">Register a new vehicle to get started.</p>
          </div>
        )}
      </div>

      {/* Floating FAB on mobile */}
      <button
        onClick={() => { setEditMode(false); setIsAddModalOpen(true); setFormLicensePlate(''); setFormType('TRUCK'); setFormTareWeight(''); setFormInsurance(''); setFormFitness(''); setFormPollution(''); setFormOwnerName(''); setFormContact(''); }}
        className={`fixed bottom-6 right-5 sm:hidden w-14 h-14 rounded-2xl flex items-center justify-center shadow-lg z-30 active:scale-95 transition-transform ${activeTab === 'OWNED' ? 'bg-emerald-500 shadow-emerald-500/30' : 'bg-[#F5A623] shadow-[#F5A623]/30'}`}>
        <Plus className="w-6 h-6 text-white" />
      </button>

      {/* Commission Modal */}
      <Modal isOpen={isCommissionModalOpen} onClose={() => setIsCommissionModalOpen(false)} title="LOG FREIGHT COMMISSION">
        <form onSubmit={handleCommissionSubmit} className="space-y-6">
          <Input label="Amount (₹) *" type="number" step="0.01" required value={amount} onChange={e => setAmount(e.target.value)} className="text-xl font-bold" />
          <Input label="Description *" type="text" required value={description} onChange={e => setDescription(e.target.value)} placeholder="e.g. Inward Transport from Farm" />
          <div className="pt-4 flex justify-end gap-3 border-t-2 border-[var(--border)]">
            <Button type="button" variant="ghost" onClick={() => setIsCommissionModalOpen(false)}>CANCEL</Button>
            <Button type="submit" className="bg-[var(--gold)] text-white" disabled={isSubmitting}>RECORD COMMISSION</Button>
          </div>
        </form>
      </Modal>

      {/* Settle Modal */}
      <Modal isOpen={isSettleModalOpen} onClose={() => setIsSettleModalOpen(false)} title="SETTLE PAYMENT">
        <form onSubmit={handleSettleSubmit} className="space-y-6">
          <Input label="Payment Amount (₹) *" type="number" step="0.01" required value={amount} onChange={e => setAmount(e.target.value)} className="text-xl font-bold" />
          <Select label="Source Account" value={selectedBankId} onChange={e => setSelectedBankId(e.target.value)}>
            <option value="">Cash Account</option>
            {banks.map(b => <option key={b.id} value={b.id}>{b.bankName} - {b.accountNumber}</option>)}
          </Select>
          <div className="pt-4 flex justify-end gap-3 border-t-2 border-[var(--border)]">
            <Button type="button" variant="ghost" onClick={() => setIsSettleModalOpen(false)}>CANCEL</Button>
            <Button type="submit" variant="primary" disabled={isSubmitting}>PAY NOW</Button>
          </div>
        </form>
      </Modal>

      {/* Expense Modal */}
      <Modal isOpen={isExpenseModalOpen} onClose={() => setIsExpenseModalOpen(false)} title="LOG VEHICLE EXPENSE">
        <form onSubmit={handleExpenseSubmit} className="space-y-6">
          <Select label="Expense Category *" required value={selectedCategoryId} onChange={e => setSelectedCategoryId(e.target.value)}>
            <option value="">Select Category...</option>
            {expenseCategories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
          </Select>
          <Input label="Amount (₹) *" type="number" step="0.01" required value={amount} onChange={e => setAmount(e.target.value)} className="text-xl font-bold" />
          <Input label="Description *" type="text" required value={description} onChange={e => setDescription(e.target.value)} placeholder="e.g. 50L Diesel, Tire Repair" />
          <Select label="Paid From" value={selectedBankId} onChange={e => setSelectedBankId(e.target.value)}>
            <option value="">Cash Account</option>
            {banks.map(b => <option key={b.id} value={b.id}>{b.bankName} - {b.accountNumber}</option>)}
          </Select>
          <div className="pt-4 flex justify-end gap-3 border-t-2 border-[var(--border)]">
            <Button type="button" variant="ghost" onClick={() => setIsExpenseModalOpen(false)}>CANCEL</Button>
            <Button type="submit" variant="primary" disabled={isSubmitting} className="bg-sky-600">LOG EXPENSE</Button>
          </div>
        </form>
      </Modal>

      {/* Add/Edit Vehicle Modal */}
      <Modal isOpen={isAddModalOpen} onClose={() => setIsAddModalOpen(false)}
        title={`${editMode ? 'Edit' : 'Register'} ${activeTab === 'OWNED' ? 'Fleet Vehicle' : 'Third-Party Vehicle'}`}>
        <form onSubmit={handleAddSubmit} className="space-y-6">
          <div className="grid grid-cols-2 gap-4">
            <Input label="License Plate *" type="text" required value={formLicensePlate} onChange={e => setFormLicensePlate(e.target.value)} className="font-mono uppercase" />
            <Select label="Type *" value={formType} onChange={e => setFormType(e.target.value)}>
              <option value="TRUCK">Truck</option>
              <option value="TRACTOR">Tractor</option>
              <option value="AUTO">Auto/Light</option>
            </Select>
          </div>
          <Input label="Tare Weight (MT) - Optional" type="number" step="0.01" value={formTareWeight} onChange={e => setFormTareWeight(e.target.value)} />

          {activeTab === 'OWNED' ? (
            <div className="space-y-4 pt-4 border-t-2 border-dashed border-[var(--dust)]">
              <h4 className="font-display font-bold uppercase tracking-widest text-emerald-400 text-xs flex items-center gap-2">
                <CheckCircle2 className="w-3.5 h-3.5" /> Compliance Documents
              </h4>
              <Input label="Insurance Expiry" type="date" value={formInsurance} onChange={e => setFormInsurance(e.target.value)} />
              <Input label="Fitness Expiry" type="date" value={formFitness} onChange={e => setFormFitness(e.target.value)} />
              <Input label="Pollution Expiry" type="date" value={formPollution} onChange={e => setFormPollution(e.target.value)} />
            </div>
          ) : (
            <div className="space-y-4 pt-4 border-t-2 border-dashed border-[var(--dust)]">
              <h4 className="font-display font-bold uppercase tracking-widest text-[#F5A623] text-xs">Owner Details</h4>
              <Input label="Owner Name" type="text" value={formOwnerName} onChange={e => setFormOwnerName(e.target.value)} />
              <Input label="Contact Number" type="text" value={formContact} onChange={e => setFormContact(e.target.value)} />
            </div>
          )}

          <div className="pt-4 flex justify-end gap-3 border-t-2 border-[var(--border)]">
            <Button type="button" variant="ghost" onClick={() => setIsAddModalOpen(false)}>CANCEL</Button>
            <Button type="submit" variant="primary" disabled={isSubmitting}
              className={activeTab === 'OWNED' ? 'bg-emerald-600' : 'bg-[var(--gold)]'}>
              {editMode ? 'UPDATE' : 'SAVE'}
            </Button>
          </div>
        </form>
      </Modal>
    </div>
  );
}

'use client';

import { useState, useMemo } from 'react';
import { toast } from 'sonner';
import { Scale, Droplets, Receipt, Clock, Truck, Trash2, Package, Plus, Tags, CheckCircle, Camera } from 'lucide-react';
import { createDraftBatchAction, finalizeBatchAction, cancelDraftBatchAction, autoSaveDraftAction } from '@/app/actions/procurement';
import { createPackingItemAction } from '@/app/actions/packingItem';
import QuickAddModal, { type EntityType } from './QuickAddModal';
import { Input, Select } from '@/components/ui/Input';
import { Button } from '@/components/ui/Button';
import { Modal } from '@/components/ui/Modal';
import { Badge } from '@/components/ui/Badge';
import { motion, AnimatePresence } from 'framer-motion';

type Supplier = { id: string; name: string; category?: string };
type Farmer = { id: string; name: string; brokerId: string };
type Product = { id: string; name: string };
type Godown = { id: string; name: string };
type Draft = { 
  id: string; supplierId: string; supplierName: string; farmerId: string | null; farmerName: string | null; productId: string | null; 
  productName: string; godownId: string | null; grossWeight: string; createdAt: string; 
  tareWeight?: string; perBagWeight?: string; farmerBagRate?: string; brokerCommissionRate?: string; 
  beforeDryingMoisture?: string; afterDryingMoisture?: string;
};

export default function WeighbridgeForm({ 
  suppliers,
  farmers = [],
  products, 
  godowns,
  pendingDrafts = [],
  initialTab = 'PADDY'
}: { 
  suppliers: Supplier[], 
  farmers?: Farmer[],
  products: Product[], 
  godowns: Godown[],
  pendingDrafts?: Draft[],
  initialTab?: 'PADDY' | 'PACKAGING'
}) {
  const [procurementTab, setProcurementTab] = useState<'PADDY' | 'PACKAGING'>(initialTab);
  const [mobileStep, setMobileStep] = useState<1 | 2 | 3>(1);
  const [showMobileQueue, setShowMobileQueue] = useState(false);

  const [localSuppliers, setLocalSuppliers] = useState<Supplier[]>(suppliers);
  const [localFarmers, setLocalFarmers] = useState(farmers);
  const [localProducts, setLocalProducts] = useState(products);
  const [localGodowns, setLocalGodowns] = useState(godowns);

  const [modalOpen, setModalOpen] = useState(false);
  const [modalEntity, setModalEntity] = useState<EntityType>('SUPPLIER');

  // Custom Confirm Modal State
  const [confirmState, setConfirmState] = useState<{isOpen: boolean, action: (() => void) | null, message: string}>({isOpen: false, action: null, message: ''});

  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [batchId, setBatchId] = useState<string | null>(null);
  const [supplierId, setSupplierId] = useState('');
  const [farmerId, setFarmerId] = useState('');
  const [productId, setProductId] = useState('');
  const [godownId, setGodownId] = useState('');
  const [grossWeight, setGrossWeight] = useState('');

  const [tareWeight, setTareWeight] = useState('');
  const [perBagWeight, setPerBagWeight] = useState('');
  const [farmerBagRate, setFarmerBagRate] = useState('');
  const [brokerCommissionRate, setBrokerCommissionRate] = useState('');
  const [weighSlip, setWeighSlip] = useState<File | null>(null);
  const [weighSlipPreview, setWeighSlipPreview] = useState<string | null>(null);
  const [beforeDryingMoisture, setBeforeDryingMoisture] = useState('');
  const [afterDryingMoisture, setAfterDryingMoisture] = useState('14.0');
  const [enableMoisture, setEnableMoisture] = useState(false);

  // Find Common Storage Godown for Packaging Bags
  const commonPackagingGodownId = useMemo(() => {
    const common = localGodowns.find(g => g.name.toLowerCase().includes('common') || g.name.toLowerCase().includes('packaging'));
    return common?.id || localGodowns[0]?.id || '';
  }, [localGodowns]);

  // Packaging form states
  const [pkgBrandName, setPkgBrandName] = useState('');
  const [pkgCapacityKg, setPkgCapacityKg] = useState('');
  const [pkgQuantityBags, setPkgQuantityBags] = useState('');
  const [pkgPerBagRate, setPkgPerBagRate] = useState('');
  const [pkgGodownId, setPkgGodownId] = useState('');
  const [pkgSupplierId, setPkgSupplierId] = useState('');
  const [pkgHsnCode, setPkgHsnCode] = useState('');
  const [isPkgSubmitting, setIsPkgSubmitting] = useState(false);

  // Separate Paddy Brokers from Bag Vendors
  const paddyBrokers = useMemo(() => {
    return localSuppliers.filter(s => s.category !== 'BAG_VENDOR');
  }, [localSuppliers]);

  const bagVendors = useMemo(() => {
    return localSuppliers.filter(s => s.category === 'BAG_VENDOR');
  }, [localSuppliers]);

  // Derive effective packaging storage godown (defaults to Common Packaging Storage Godown)
  const effectivePkgGodownId = pkgGodownId || commonPackagingGodownId;

  const availableFarmers = useMemo(() => {
    return localFarmers.filter(f => f.brokerId === supplierId);
  }, [localFarmers, supplierId]);

  // Real-time calculations
  const netWeight = useMemo(() => {
    const gross = parseFloat(grossWeight);
    const tare = parseFloat(tareWeight);
    if (!isNaN(gross) && !isNaN(tare) && gross > tare) {
      return (gross - tare).toFixed(2);
    }
    return '0.00';
  }, [grossWeight, tareWeight]);

  const dryingShortage = useMemo(() => {
    const net = parseFloat(netWeight);
    const beforeM = parseFloat(beforeDryingMoisture);
    const afterM = parseFloat(afterDryingMoisture);
    if (net > 0 && beforeM > afterM && afterM < 100) {
      const num = beforeM - afterM;
      const den = 100 - afterM;
      return (net * (num / den)).toFixed(2);
    }
    return '0.00';
  }, [netWeight, beforeDryingMoisture, afterDryingMoisture]);

  const finalGodownWeight = useMemo(() => {
    const net = parseFloat(netWeight);
    const shortage = parseFloat(dryingShortage);
    if (net > 0) {
      return (net - shortage).toFixed(2);
    }
    return '0.00';
  }, [netWeight, dryingShortage]);

  const numberOfBagsCalc = useMemo(() => {
    const net = parseFloat(netWeight);
    const pbw = parseFloat(perBagWeight);
    if (net > 0 && pbw > 0) {
      return (net / pbw).toFixed(2);
    }
    return 0;
  }, [netWeight, perBagWeight]);

  const farmerTotalPayable = useMemo(() => {
    const rate = parseFloat(farmerBagRate);
    const bags = parseFloat(String(numberOfBagsCalc));
    if (bags > 0 && rate > 0) {
      return (bags * rate).toFixed(2);
    }
    return '0.00';
  }, [numberOfBagsCalc, farmerBagRate]);

  const brokerCommissionTotal = useMemo(() => {
    const rate = parseFloat(brokerCommissionRate);
    const bags = parseFloat(String(numberOfBagsCalc));
    if (bags > 0 && rate > 0) {
      return (bags * rate).toFixed(2);
    }
    return '0.00';
  }, [numberOfBagsCalc, brokerCommissionRate]);

  const ratePerKg = useMemo(() => {
    const rate = parseFloat(farmerBagRate);
    const pbw = parseFloat(perBagWeight);
    if (rate > 0 && pbw > 0) {
      return (rate / pbw).toFixed(2);
    }
    return '0.00';
  }, [farmerBagRate, perBagWeight]);

  const clearForm = () => {
    setBatchId(null);
    setSupplierId('');
    setFarmerId('');
    setProductId('');
    setGodownId('');
    setGrossWeight('');
    setTareWeight('');
    setPerBagWeight('');
    setFarmerBagRate('');
    setBrokerCommissionRate('');
    setBeforeDryingMoisture('');
    setAfterDryingMoisture('14.0');
    setErrorMsg(null);
    setMobileStep(1);
  };

  const loadDraft = (draft: Draft) => {
    setProcurementTab('PADDY');
    setBatchId(draft.id);
    setSupplierId(draft.supplierId);
    setFarmerId(draft.farmerId || '');
    setProductId(draft.productId || '');
    setGodownId(draft.godownId || '');
    setGrossWeight(draft.grossWeight);
    setTareWeight(draft.tareWeight || '');
    setPerBagWeight(draft.perBagWeight || '');
    setFarmerBagRate(draft.farmerBagRate || '');
    setBrokerCommissionRate(draft.brokerCommissionRate || '');
    setBeforeDryingMoisture(draft.beforeDryingMoisture || '');
    setAfterDryingMoisture(draft.afterDryingMoisture || '14.0');
    setErrorMsg(null);
  };

  const handleAutoSave = async () => {
    if (!batchId) return;
    try {
      const formData = new FormData();
      formData.append('batchId', batchId);
      if (farmerId !== undefined) formData.append('farmerId', farmerId);
      if (tareWeight) formData.append('tareWeight', tareWeight);
      if (perBagWeight) formData.append('perBagWeight', perBagWeight);
      if (farmerBagRate) formData.append('farmerBagRate', farmerBagRate);
      if (brokerCommissionRate) formData.append('brokerCommissionRate', brokerCommissionRate);
      if (beforeDryingMoisture) formData.append('beforeDryingMoisture', beforeDryingMoisture);
      if (afterDryingMoisture) formData.append('afterDryingMoisture', afterDryingMoisture);

      await autoSaveDraftAction(formData);
    } catch (e) {
      console.error("Auto-save failed", e);
    }
  };

  const handleDraftSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setErrorMsg(null);
    try {
      const formData = new FormData();
      formData.append('supplierId', supplierId);
      if (farmerId) formData.append('farmerId', farmerId);
      formData.append('productId', productId);
      formData.append('godownId', godownId);
      formData.append('grossWeight', grossWeight);

      await createDraftBatchAction(formData);
      toast.success('Draft saved successfully! Truck added to queue.');
      clearForm();
    } catch (err) {
      setErrorMsg(err instanceof Error ? err.message : 'Failed to save draft');
    }
  };

  const handleFinalizeSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!batchId) return;
    setErrorMsg(null);

    try {
      const formData = new FormData();
      formData.append('batchId', batchId);
      formData.append('tareWeight', tareWeight);
      formData.append('beforeDryingMoisture', beforeDryingMoisture);
      formData.append('afterDryingMoisture', afterDryingMoisture);
      formData.append('perBagWeight', perBagWeight);
      formData.append('farmerBagRate', farmerBagRate);
      formData.append('brokerCommissionRate', brokerCommissionRate);

      await finalizeBatchAction(formData);
      toast.success('Batch finalized! Sent to Cashier for Approval.');
      clearForm();
    } catch (err) {
      setErrorMsg(err instanceof Error ? err.message : 'Failed to finalize batch');
    }
  };

  const handlePackagingProcurementSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsPkgSubmitting(true);
    setErrorMsg(null);

    try {
      const formData = new FormData();
      formData.append('brandName', pkgBrandName);
      formData.append('capacityKg', pkgCapacityKg);
      formData.append('quantityBags', pkgQuantityBags);
      formData.append('perBagRate', pkgPerBagRate);
      formData.append('godownId', effectivePkgGodownId);
      if (pkgSupplierId) formData.append('supplierId', pkgSupplierId);
      if (pkgHsnCode) formData.append('hsnCode', pkgHsnCode);

      await createPackingItemAction(formData);
      toast.success('Packaging Bags Procured! Sent to Cashier.');
      setPkgBrandName('');
      setPkgCapacityKg('');
      setPkgQuantityBags('');
      setPkgPerBagRate('');
      setPkgSupplierId('');
      setPkgHsnCode('');
    } catch (err) {
      setErrorMsg(err instanceof Error ? err.message : 'Failed to procure packaging material');
    } finally {
      setIsPkgSubmitting(false);
    }
  };

  const executeCancelDraft = async () => {
    if (!batchId) return;
    setConfirmState({ ...confirmState, isOpen: false });
    setErrorMsg(null);
    try {
      const formData = new FormData();
      formData.append('batchId', batchId);
      await cancelDraftBatchAction(formData);
      toast.success('Truck entry cancelled successfully.');
      clearForm();
    } catch (err) {
      setErrorMsg(err instanceof Error ? err.message : 'Failed to cancel draft');
    }
  };

  const handleCancelDraft = () => {
    setConfirmState({
      isOpen: true,
      message: 'Are you sure you want to cancel this pending truck? This will permanently delete the draft.',
      action: executeCancelDraft
    });
  };

  const handleAddSuccess = (newItem: { id: string; name: string; brokerId?: string }) => {
    setModalOpen(false);
    if (modalEntity === 'SUPPLIER') {
      const supplierItem = { ...newItem, category: 'PADDY_BROKER' };
      setLocalSuppliers(prev => [...prev, supplierItem]);
      setSupplierId(newItem.id);
      setFarmerId('');
    } else if (modalEntity === 'BAG_VENDOR') {
      const vendorItem = { ...newItem, category: 'BAG_VENDOR' };
      setLocalSuppliers(prev => [...prev, vendorItem]);
      setPkgSupplierId(newItem.id);
    } else if (modalEntity === 'FARMER') {
      const farmerItem: Farmer = {
        id: newItem.id,
        name: newItem.name,
        brokerId: newItem.brokerId || supplierId,
      };
      setLocalFarmers([...localFarmers, farmerItem]);
      setFarmerId(newItem.id);
    } else if (modalEntity === 'PRODUCT') {
      setLocalProducts([...localProducts, newItem]);
      setProductId(newItem.id);
    } else if (modalEntity === 'GODOWN') {
      setLocalGodowns([...localGodowns, newItem]);
      setGodownId(newItem.id);
      setPkgGodownId(newItem.id);
    }
  };

  return (
    <div className="max-w-7xl mx-auto space-y-6 mt-4">

      {/* Top Procurement Mode Selector Tabs */}
      <div className="flex bg-[#1A1A1A] p-1.5 rounded-2xl w-full sm:w-auto border border-neutral-800 shadow-xl">
        <button
          type="button"
          onClick={() => setProcurementTab('PADDY')}
          className={`flex-1 justify-center px-4 sm:px-6 py-3 rounded-xl font-black uppercase tracking-wider text-xs sm:text-sm flex items-center gap-2 transition-all ${procurementTab === 'PADDY' ? 'bg-[#F5A623] text-black shadow-lg' : 'text-neutral-500 hover:text-neutral-300'}`}
        >
          <Scale className="w-4 h-4" />
          Paddy Inbound
        </button>

        <button
          type="button"
          onClick={() => setProcurementTab('PACKAGING')}
          className={`flex-1 justify-center px-4 sm:px-6 py-3 rounded-xl font-black uppercase tracking-wider text-xs sm:text-sm flex items-center gap-2 transition-all ${procurementTab === 'PACKAGING' ? 'bg-neutral-600 text-white shadow-lg' : 'text-neutral-500 hover:text-neutral-300'}`}
        >
          <Tags className="w-4 h-4" />
          Packaging Inbound
        </button>
      </div>

      <AnimatePresence mode="wait">
        {procurementTab === 'PADDY' ? (
          <motion.div 
            key="paddy"
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            className="flex flex-col lg:flex-row gap-8"
          >

            {/* LEFT: Pending Drafts Queue */}
            <div className="lg:w-1/3 flex flex-col gap-4">
              <div className="bg-[#111111] rounded-2xl border border-neutral-800 flex-1 flex flex-col overflow-hidden">
                <button 
                  type="button"
                  onClick={() => setShowMobileQueue(!showMobileQueue)}
                  className="px-4 py-4 flex justify-between items-center border-b border-neutral-800 w-full text-left active:bg-neutral-900 transition-colors"
                >
                  <h3 className="font-black text-base text-white flex items-center gap-2">
                    <Clock className="w-4 h-4 text-[#F5A623]" /> Truck Queue
                  </h3>
                  <div className="flex items-center gap-2">
                    <span className="text-[10px] font-black uppercase px-2 py-0.5 bg-[#F5A623]/20 text-[#F5A623] rounded-lg border border-[#F5A623]/30">{pendingDrafts.length} waiting</span>
                    <span className="lg:hidden text-neutral-400 text-lg font-bold">{showMobileQueue ? '−' : '+'}</span>
                  </div>
                </button>
                <div className={`p-3 space-y-2 max-h-[500px] overflow-y-auto ${showMobileQueue ? 'block' : 'hidden lg:block'}`}>
                  {pendingDrafts.length === 0 ? (
                    <div className="py-10 text-center">
                      <Truck className="w-8 h-8 text-neutral-700 mx-auto mb-2" />
                      <p className="text-xs font-black uppercase text-neutral-600">No trucks unloading</p>
                    </div>
                  ) : (
                    <div>
                      {pendingDrafts.map(draft => (
                        <div 
                          key={draft.id} 
                          onClick={() => { loadDraft(draft); setMobileStep(1); setShowMobileQueue(false); }}
                          className={`p-3 rounded-xl border cursor-pointer transition-all mb-2 active:scale-[0.98] ${batchId === draft.id ? 'bg-[#F5A623]/20 border-[#F5A623]/50' : 'bg-[#1A1A1A] border-neutral-800 hover:border-neutral-600'}`}
                        >
                          <div className="flex justify-between items-start mb-1.5">
                            <span className="font-black text-sm text-white uppercase truncate flex-1 mr-2">
                              {draft.supplierName}
                            </span>
                            <span className={`text-[10px] font-black px-2 py-0.5 rounded-lg border shrink-0 ${batchId === draft.id ? 'bg-[#F5A623]/30 text-[#F5A623] border-[#F5A623]/40' : 'bg-neutral-800 text-neutral-400 border-neutral-700'}`}>{draft.grossWeight} kg</span>
                          </div>
                          {draft.farmerName && <div className="text-[10px] font-bold text-neutral-500 mb-1">{draft.farmerName}</div>}
                          <div className="text-[10px] font-bold flex items-center text-neutral-500">
                            <Truck className="w-3 h-3 mr-1" /> {draft.productName}
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
                <div className={`p-3 border-t border-neutral-800 ${showMobileQueue ? 'block' : 'hidden lg:block'}`}>
                   <button type="button" onClick={() => { clearForm(); setMobileStep(1); setShowMobileQueue(false); }}
                     className="w-full py-2.5 rounded-xl border border-neutral-700 text-neutral-400 font-black uppercase text-xs tracking-wider hover:border-neutral-500 hover:text-neutral-200 transition-colors flex items-center justify-center gap-2">
                     <Plus className="w-3.5 h-3.5" /> New Entry
                   </button>
                </div>
              </div>
            </div>

            {/* RIGHT: Weighbridge Form */}
            <div className="lg:w-2/3 bg-[#111111] rounded-2xl border border-neutral-800 overflow-hidden">
              <div className="bg-gradient-to-r from-emerald-950 to-[#0E1A0E] px-5 py-5 sm:px-8 sm:py-6 border-b border-neutral-800 flex items-start justify-between gap-3">
                <div>
                  <h2 className="font-black text-xl sm:text-2xl text-white flex items-center gap-3">
                    <div className="p-2 bg-emerald-500/20 rounded-xl">
                      <Scale className="h-5 w-5 text-emerald-400" />
                    </div>
                    {batchId ? 'Finalize Unloaded Truck' : 'New Weighbridge Entry'}
                  </h2>
                  <p className="mt-1.5 text-neutral-500 text-xs sm:text-sm font-medium ml-1">
                    {batchId ? 'Enter tare weight and moisture to finalize.' : 'Log truck arrival and gross weight.'}
                  </p>
                </div>
                {batchId && (
                  <div className="shrink-0 px-3 py-2 bg-emerald-500/20 border border-emerald-700/40 rounded-2xl">
                    <p className="text-[9px] font-black uppercase text-emerald-400/70">Finalizing</p>
                    <p className="text-emerald-400 font-black text-sm">{grossWeight} kg</p>
                  </div>
                )}
              </div>

              <div className="p-5 sm:p-8">
                {errorMsg && (
                  <div className="mb-5 p-4 bg-red-950/50 border border-red-900/60 rounded-xl text-red-400 font-bold text-sm flex items-center gap-2">
                    <span>⚠️</span> {errorMsg}
                  </div>
                )}

                <form className="space-y-0 lg:space-y-8" onSubmit={batchId ? handleFinalizeSubmit : handleDraftSubmit}>

                  {/* Mobile Wizard Progress */}
                  <div className="lg:hidden flex items-center gap-0 mb-6 pb-5 border-b border-neutral-800">
                    {[{n:1,l:'Inbound'},{n:2,l:'Quality'},{n:3,l:'Final'}].map((s, i) => (
                      <div key={s.n} className="flex items-center flex-1">
                        <div className="flex flex-col items-center gap-1 flex-1">
                          <div className={`w-7 h-7 rounded-full flex items-center justify-center font-black text-xs border-2 transition-all ${mobileStep >= s.n ? 'bg-emerald-500 border-emerald-500 text-white' : 'bg-[#1A1A1A] border-neutral-700 text-neutral-500'}`}>{s.n}</div>
                          <span className={`text-[9px] font-black uppercase tracking-wider ${mobileStep >= s.n ? 'text-emerald-400' : 'text-neutral-600'}`}>{s.l}</span>
                        </div>
                        {i < 2 && <div className={`h-0.5 flex-1 mx-1 rounded transition-all mb-4 ${mobileStep > s.n ? 'bg-emerald-500' : 'bg-neutral-800'}`} />}
                      </div>
                    ))}
                  </div>

                  {/* Section 1 */}
                  <div className={`space-y-5 ${mobileStep === 1 ? 'block' : 'hidden lg:block'}`}>
                    <p className="text-[10px] font-black uppercase tracking-widest text-neutral-500">Step 1 — Physical Inbound</p>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6 stagger">
                      <div className="flex gap-2 items-end animate-fade-up">
                        <Select
                          label="Paddy Broker"
                          value={supplierId}
                          onChange={(e) => { setSupplierId(e.target.value); setFarmerId(''); }}
                          required
                          disabled={!!batchId}
                        >
                          <option value="">Select Broker...</option>
                          {paddyBrokers.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                        </Select>
                        <Button type="button" variant="ghost" onClick={() => { setModalEntity('SUPPLIER'); setModalOpen(true); }} disabled={!!batchId} className="px-3 mb-[2px]">
                          <Plus className="w-5 h-5" />
                        </Button>
                      </div>

                      {supplierId && (
                        <div className="flex gap-2 items-end animate-fade-up">
                          <Select
                            label="Farmer (Optional)"
                            value={farmerId}
                            onChange={(e) => setFarmerId(e.target.value)}
                            onBlur={handleAutoSave}
                            disabled={!!batchId}
                          >
                            <option value="">Select Farmer...</option>
                            {availableFarmers.map(f => <option key={f.id} value={f.id}>{f.name}</option>)}
                          </Select>
                          <Button type="button" variant="ghost" onClick={() => { setModalEntity('FARMER'); setModalOpen(true); }} disabled={!!batchId} className="px-3 mb-[2px]">
                            <Plus className="w-5 h-5" />
                          </Button>
                        </div>
                      )}

                      <div className="flex gap-2 items-end animate-fade-up">
                        <Select
                          label="Paddy Type"
                          value={productId}
                          onChange={(e) => setProductId(e.target.value)}
                          required
                          disabled={!!batchId}
                        >
                          <option value="">Select Product...</option>
                          {localProducts.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                        </Select>
                        <Button type="button" variant="ghost" onClick={() => { setModalEntity('PRODUCT'); setModalOpen(true); }} disabled={!!batchId} className="px-3 mb-[2px]">
                          <Plus className="w-5 h-5" />
                        </Button>
                      </div>

                      <div className="flex gap-2 items-end animate-fade-up">
                        <Select
                          label="Destination Godown"
                          value={godownId}
                          onChange={(e) => setGodownId(e.target.value)}
                          required
                          disabled={!!batchId}
                        >
                          <option value="">Select Godown...</option>
                          {localGodowns
                            .filter(g => !g.name.toLowerCase().includes('common') && !g.name.toLowerCase().includes('packaging'))
                            .map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
                        </Select>
                        <Button type="button" variant="ghost" onClick={() => { setModalEntity('GODOWN'); setModalOpen(true); }} disabled={!!batchId} className="px-3 mb-[2px]">
                          <Plus className="w-5 h-5" />
                        </Button>
                      </div>

                      <div className="animate-fade-up">
                        <Input
                          label="Gross Weight (KG)"
                          type="number"
                          step="0.01"
                          required
                          disabled={!!batchId}
                          value={grossWeight}
                          onChange={(e) => setGrossWeight(e.target.value)}
                          placeholder="e.g. 250.00"
                          inputMode="decimal"
                          pattern="[0-9]*"
                        />
                      </div>

                      {batchId && (
                        <div className="animate-fade-up">
                          <Input
                            label="Tare Weight (KG)"
                            type="number"
                            step="0.01"
                            required={!!batchId}
                            value={tareWeight}
                            onChange={(e) => setTareWeight(e.target.value)}
                            onBlur={handleAutoSave}
                            placeholder="e.g. 100.00"
                            className="border-[var(--green)] focus:border-[var(--green)]"
                            inputMode="decimal"
                            pattern="[0-9]*"
                          />
                        </div>
                      )}
                    </div>

                    {/* Next Button for Mobile */}
                    {!!batchId && (
                      <div className="lg:hidden pt-4">
                         <Button type="button" onClick={() => setMobileStep(2)} variant="primary" className="w-full">
                           NEXT STEP <CheckCircle className="w-4 h-4 ml-2" />
                         </Button>
                      </div>
                    )}
                  </div>

                  {batchId && (
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className={`space-y-6 pt-6 lg:border-t-4 border-[var(--border)] ${mobileStep === 2 ? 'block' : 'hidden lg:block'}`}>
                      <h3 className="font-display font-black text-xl text-[var(--text)] uppercase flex items-center border-b-2 border-dashed border-[var(--dust)] pb-2">
                        2. PAYMENT & QUALITY DETAILS
                      </h3>

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 stagger">
                        <div className="animate-fade-up">
                          <Input
                            label="Per Bag Weight (KG)"
                            type="number"
                            step="0.1"
                            required
                            value={perBagWeight}
                            onChange={(e) => setPerBagWeight(e.target.value)}
                            onBlur={handleAutoSave}
                            icon={<Package className="w-4 h-4" />}
                            placeholder="e.g. 70.5"
                            inputMode="decimal"
                            pattern="[0-9]*"
                          />
                        </div>

                        <div className="animate-fade-up">
                          <Input
                            label="Farmer Bag Rate (₹)"
                            type="number"
                            step="0.01"
                            required
                            value={farmerBagRate}
                            onChange={(e) => setFarmerBagRate(e.target.value)}
                            onBlur={handleAutoSave}
                            icon={<Receipt className="w-4 h-4 text-[var(--green)]" />}
                            placeholder="e.g. 2100.00"
                            inputMode="decimal"
                            pattern="[0-9]*"
                          />
                        </div>

                        <div className="animate-fade-up">
                          <Input
                            label="Broker Comm. / Bag (₹)"
                            type="number"
                            step="0.01"
                            required
                            value={brokerCommissionRate}
                            onChange={(e) => setBrokerCommissionRate(e.target.value)}
                            onBlur={handleAutoSave}
                            icon={<Receipt className="w-4 h-4 text-blue-600" />}
                            placeholder="e.g. 50.00"
                            inputMode="decimal"
                            pattern="[0-9]*"
                          />
                        </div>
                      </div>

                      <div className="mt-8 space-y-4 animate-fade-up">
                        <label className="flex items-center gap-3 cursor-pointer group">
                          <input 
                            type="checkbox" 
                            checked={enableMoisture} 
                            onChange={(e) => {
                              setEnableMoisture(e.target.checked);
                              if (!e.target.checked) {
                                setBeforeDryingMoisture('');
                                setAfterDryingMoisture('14.0');
                              }
                            }} 
                            className="w-5 h-5 border-2 border-[var(--border)] rounded-sm text-[var(--gold)] focus:ring-[var(--gold)] bg-[var(--surface)] transition-all cursor-pointer"
                          />
                          <span className="font-display font-bold uppercase tracking-wider text-sm text-[var(--text)] group-hover:text-[var(--gold)] transition-colors">
                            Enable Moisture Deduction
                          </span>
                        </label>

                        {enableMoisture && (
                          <div className="grid grid-cols-2 gap-4 p-4 border-2 border-[var(--border)] bg-[var(--surface-2)] shadow-brutal-sm rounded-sm">
                            <Input
                              label="Moisture (Before) %"
                              type="number"
                              step="0.1"
                              required={enableMoisture}
                              value={beforeDryingMoisture}
                              onChange={(e) => setBeforeDryingMoisture(e.target.value)}
                              onBlur={handleAutoSave}
                              icon={<Droplets className="w-4 h-4 text-blue-500" />}
                              placeholder="e.g. 21.0"
                              inputMode="decimal"
                              pattern="[0-9]*"
                            />
                            <Input
                              label="Moisture (After) %"
                              type="number"
                              step="0.1"
                              required={enableMoisture}
                              value={afterDryingMoisture}
                              onChange={(e) => setAfterDryingMoisture(e.target.value)}
                              onBlur={handleAutoSave}
                              icon={<Droplets className="w-4 h-4 text-blue-400" />}
                              placeholder="e.g. 14.0"
                              inputMode="decimal"
                              pattern="[0-9]*"
                            />
                          </div>
                        )}
                      </div>

                      {/* SUMMARY DASHBOARD inside form */}
                      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 p-4 bg-[var(--charcoal)] border-4 border-[var(--gold)] shadow-brutal-lg rounded-sm mt-8 text-white lg:sticky lg:bottom-4 z-10 sticky top-[60px]">
                        <div>
                          <p className="text-[10px] font-display font-bold uppercase tracking-widest text-[var(--gold)]">Net Weight</p>
                          <p className="text-xl font-black tabular-nums mt-1">{netWeight} <span className="text-xs font-normal">kg</span></p>
                        </div>
                        <div>
                          <p className="text-[10px] font-display font-bold uppercase tracking-widest text-[var(--gold)]">Bags</p>
                          <p className="text-xl font-black tabular-nums mt-1">{numberOfBagsCalc}</p>
                        </div>
                        <div>
                          <p className="text-[10px] font-display font-bold uppercase tracking-widest text-[var(--gold)]">Broker</p>
                          <p className="text-xl font-black tabular-nums mt-1">₹{brokerCommissionTotal}</p>
                        </div>
                        <div>
                          <p className="text-[10px] font-display font-bold uppercase tracking-widest text-[var(--green)]">Farmer Payable</p>
                          <p className="text-xl font-black tabular-nums mt-1 text-[var(--green)]">₹{farmerTotalPayable}</p>
                        </div>
                      </div>

                      <div className="lg:hidden flex gap-4 pt-4">
                        <Button type="button" onClick={() => setMobileStep(1)} variant="ghost" className="flex-1">BACK</Button>
                        <Button type="button" onClick={() => setMobileStep(3)} variant="primary" className="flex-1">NEXT STEP</Button>
                      </div>
                    </motion.div>
                  )}
                  {/* Camera Integration for Docket */}
                  <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className={`mt-8 mb-4 ${mobileStep === 3 || (!batchId && mobileStep === 1) ? 'block' : 'hidden lg:block'}`}>
                    <div className="relative border-2 border-dashed border-[var(--blue)] bg-[var(--surface-2)] p-4 sm:p-6 flex flex-col items-center justify-center text-center group overflow-hidden transition-all hover:bg-[var(--surface)] min-h-[120px]">
                      <input 
                        type="file" 
                        accept="image/*" 
                        capture="environment" 
                        className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
                        onChange={(e) => {
                          const file = e.target.files?.[0];
                          if (file) {
                            setWeighSlip(file);
                            setWeighSlipPreview(URL.createObjectURL(file));
                          }
                        }}
                      />
                      {weighSlipPreview ? (
                        <div className="relative w-full aspect-[2/1] sm:aspect-video bg-black flex items-center justify-center">
                          {/* eslint-disable-next-line @next/next/no-img-element */}
                          <img src={weighSlipPreview} alt="Weigh-slip" className="max-h-full max-w-full object-contain" />
                          <div className="absolute inset-0 bg-black/50 flex flex-col items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                            <Camera className="w-8 h-8 text-white mb-2" />
                            <span className="font-display font-black text-white uppercase tracking-widest text-xs">Retake Photo</span>
                          </div>
                        </div>
                      ) : (
                        <div className="flex flex-col sm:flex-col items-center justify-center">
                          <div className="w-12 h-12 sm:w-16 sm:h-16 bg-[var(--blue)] text-white rounded-full flex items-center justify-center mb-2 sm:mb-3 group-hover:scale-110 transition-transform">
                            <Camera className="w-6 h-6 sm:w-8 sm:h-8" />
                          </div>
                          <p className="font-display font-black text-[var(--text)] uppercase tracking-widest text-sm sm:text-base mb-1">Snap Weigh-slip Docket</p>
                          <p className="text-[10px] sm:text-xs text-[var(--muted)] font-medium">Use mobile camera to attach physical receipt</p>
                        </div>
                      )}
                    </div>
                  </motion.div>
                  {/* Action Bar */}
                  <div className={`w-full bg-[var(--surface-2)] sm:bg-transparent p-4 sm:p-0 sm:pt-8 sm:border-t-2 border-[var(--border)] flex justify-between items-center mt-8 ${mobileStep === 3 || !batchId ? 'flex' : 'hidden lg:flex'}`}>
                    <div>
                      {batchId && (
                        <Button
                          type="button"
                          variant="danger"
                          onClick={handleCancelDraft}
                          className="flex items-center w-full sm:w-auto"
                        >
                          <Trash2 className="w-4 h-4 sm:mr-2" /> <span className="hidden sm:inline">CANCEL</span>
                        </Button>
                      )}
                    </div>
                    <div className="flex gap-2 sm:gap-4 w-full sm:w-auto justify-end">
                      {batchId && (
                        <Button type="button" variant="ghost" onClick={() => setMobileStep(2)} className="flex-1 sm:flex-none lg:hidden">
                          BACK
                        </Button>
                      )}
                      <Button type="submit" variant="primary" className="flex-1 sm:flex-none py-3 sm:py-2 text-lg sm:text-sm">
                        {batchId ? (
                          <span className="flex items-center justify-center"><CheckCircle className="w-5 h-5 mr-2" /> FINALIZE</span>
                        ) : 'SAVE ENTRY'}
                      </Button>
                    </div>
                  </div>
                </form>
              </div>
            </div>
          </motion.div>
        ) : (
          /* TAB 2: PACKAGING MATERIAL & BAG INBOUND PROCUREMENT FORM */
          <motion.div 
            key="pkg"
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            className="max-w-4xl mx-auto card-brutal p-0 overflow-hidden"
          >
            <div className="bg-[var(--charcoal)] p-6 sm:p-8 text-white border-b-2 border-[var(--border)]">
              <h2 className="font-display font-black text-2xl flex items-center">
                <Tags className="h-7 w-7 mr-3 text-[var(--gold)]" />
                PACKAGING PROCUREMENT
              </h2>
              <p className="mt-2 text-white/80 text-sm font-medium">
                Log new branded bag arrivals to route to Cashier for payment approval and store stock in Common Packaging Godown.
              </p>
            </div>

            <div className="p-6 sm:p-8">
              {errorMsg && (
                <div className="mb-6 p-4 bg-red-50 border-2 border-red-500 shadow-brutal-sm text-red-700 font-bold font-display text-sm flex items-center uppercase">
                  ⚠️ {errorMsg}
                </div>
              )}

              <form className="space-y-8" onSubmit={handlePackagingProcurementSubmit}>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 stagger">
                  <div className="animate-fade-up">
                    <Input
                      label="Brand Name *"
                      type="text"
                      required
                      value={pkgBrandName}
                      onChange={(e) => setPkgBrandName(e.target.value)}
                      placeholder="e.g. Royal Gold Rice Bags"
                    />
                  </div>

                  <div className="animate-fade-up">
                    <Input
                      label="Bag Capacity (KG) *"
                      type="number"
                      step="0.01"
                      required
                      value={pkgCapacityKg}
                      onChange={(e) => setPkgCapacityKg(e.target.value)}
                      placeholder="e.g. 25"
                      inputMode="decimal"
                      pattern="[0-9]*"
                    />
                  </div>

                  <div className="animate-fade-up">
                    <Input
                      label="Number of Bags *"
                      type="number"
                      step="1"
                      required
                      value={pkgQuantityBags}
                      onChange={(e) => setPkgQuantityBags(e.target.value)}
                      placeholder="e.g. 1000"
                      inputMode="decimal"
                      pattern="[0-9]*"
                    />
                  </div>

                  <div className="animate-fade-up">
                    <Input
                      label="Per Bag Rate (₹) *"
                      type="number"
                      step="0.01"
                      required
                      value={pkgPerBagRate}
                      onChange={(e) => setPkgPerBagRate(e.target.value)}
                      icon={<Receipt className="w-4 h-4" />}
                      placeholder="e.g. 15.50"
                      inputMode="decimal"
                      pattern="[0-9]*"
                    />
                  </div>

                  <div className="flex gap-2 items-end animate-fade-up">
                    <Select
                      label="Bag Vendor (Optional)"
                      value={pkgSupplierId}
                      onChange={(e) => setPkgSupplierId(e.target.value)}
                    >
                      <option value="">Select Vendor...</option>
                      {bagVendors.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                    </Select>
                    <Button type="button" variant="ghost" onClick={() => { setModalEntity('BAG_VENDOR'); setModalOpen(true); }} className="px-3 mb-[2px]">
                      <Plus className="w-5 h-5" />
                    </Button>
                  </div>
                </div>

                {pkgQuantityBags && pkgPerBagRate && (
                  <div className="p-6 bg-[var(--surface-2)] border-2 border-[var(--border)] shadow-brutal-sm flex justify-between items-center animate-fade-up">
                    <span className="font-display font-black uppercase tracking-wider text-[var(--text)]">Total Outbound Cost:</span>
                    <span className="text-2xl font-black tabular-nums text-[var(--gold)]">
                      ₹ {(parseFloat(pkgQuantityBags) * parseFloat(pkgPerBagRate)).toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                    </span>
                  </div>
                )}

                {/* Action Bar */}
                <div className="w-full sm:bg-transparent p-4 sm:p-0 sm:pt-8 sm:border-t-2 border-[var(--border)] flex justify-end mt-8">
                  <Button
                    type="submit"
                    variant="primary"
                    disabled={isPkgSubmitting || !pkgBrandName || !pkgCapacityKg || !pkgQuantityBags || !pkgPerBagRate || !effectivePkgGodownId}
                    className="w-full sm:w-auto py-4 sm:py-2 text-lg sm:text-sm"
                  >
                    {isPkgSubmitting ? 'PROCURING...' : 'PROCURE BAGS'}
                  </Button>
                </div>
              </form>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <Modal 
        isOpen={confirmState.isOpen} 
        onClose={() => setConfirmState({...confirmState, isOpen: false})}
        title="Confirm Action"
      >
        <p className="font-medium text-[var(--text)] mb-6">{confirmState.message}</p>
        <div className="flex justify-end gap-3">
          <Button variant="ghost" onClick={() => setConfirmState({...confirmState, isOpen: false})}>Cancel</Button>
          <Button variant="danger" onClick={confirmState.action || undefined}>Confirm</Button>
        </div>
      </Modal>

      <QuickAddModal 
        entityType={modalEntity}
        isOpen={modalOpen}
        onClose={() => setModalOpen(false)}
        onSuccess={handleAddSuccess}
        extraContext={{ brokerId: supplierId }}
      />
    </div>
  );
}

'use client';

import Link from 'next/link';
import { ArrowLeft, LogOut, Wifi, WifiOff, Wheat } from 'lucide-react';
import { signOut, useSession } from 'next-auth/react';

export interface BreadcrumbItem {
  label: string;
  href?: string;
}

interface AppHeaderProps {
  title: string;
  subtitle?: string;
  /** If omitted, defaults to /dashboard */
  backHref?: string;
  /** Omit to hide back button (e.g. dashboard) */
  showBack?: boolean;
  /** Breadcrumb items shown between back button and title */
  breadcrumbs?: BreadcrumbItem[];
  /** Optional icon rendered next to title */
  icon?: React.ReactNode;
  /** Optional right-side slot — CTAs, export buttons, etc */
  actions?: React.ReactNode;
  /** Whether to show the ERP logo (dashboard only) */
  showLogo?: boolean;
  /** Override online status display (for client components that track it) */
  isOnline?: boolean | null;
}

const ROLE_COLOR: Record<string, string> = {
  ADMIN: 'bg-red-950/60 text-red-300 border-red-900/60',
  MANAGER: 'bg-purple-950/60 text-purple-300 border-purple-900/60',
  ACCOUNTANT: 'bg-sky-950/60 text-sky-300 border-sky-900/60',
  WEIGHBRIDGE_OPERATOR: 'bg-amber-950/60 text-amber-300 border-amber-900/60',
  FLOOR_MANAGER: 'bg-emerald-950/60 text-emerald-300 border-emerald-900/60',
};

const ROLE_SHORT: Record<string, string> = {
  ADMIN: 'Admin',
  MANAGER: 'Mgr',
  ACCOUNTANT: 'Acct',
  WEIGHBRIDGE_OPERATOR: 'WB Op',
  FLOOR_MANAGER: 'Floor',
};

export function AppHeader({
  title,
  subtitle,
  backHref = '/dashboard',
  showBack = true,
  breadcrumbs,
  icon,
  actions,
  showLogo = false,
  isOnline = null,
}: AppHeaderProps) {
  const { data: session } = useSession();
  const role = session?.user?.role ?? '';
  const name = session?.user?.name ?? '';

  return (
    <header className="sticky top-0 z-50 bg-[#0A0A0A]/95 backdrop-blur-md border-b border-[#F5A623]/20">
      <div className="max-w-[1400px] mx-auto px-3 sm:px-6 h-14 sm:h-16 flex items-center justify-between gap-3">

        {/* ── LEFT: Logo / Back / Breadcrumbs ── */}
        <div className="flex items-center gap-2.5 min-w-0 flex-1">

          {showLogo ? (
            <div className="flex items-center gap-2.5 shrink-0">
              <div className="w-8 h-8 bg-[#F5A623] rounded-xl flex items-center justify-center shadow-lg shadow-[#F5A623]/20">
                <Wheat className="w-4 h-4 text-black" />
              </div>
              <div className="hidden sm:block">
                <p className="font-black text-white text-sm leading-none tracking-tight">RICE MILL</p>
                <p className="text-[9px] font-black uppercase text-[#F5A623]/70 tracking-[0.2em]">ERP System</p>
              </div>
            </div>
          ) : showBack ? (
            <Link href={backHref} aria-label="Go back">
              <div className="w-9 h-9 sm:w-10 sm:h-10 flex items-center justify-center bg-neutral-900 border border-neutral-800 rounded-xl hover:border-[#F5A623]/60 hover:bg-neutral-800 transition-all active:scale-95 shrink-0 group">
                <ArrowLeft className="w-4 h-4 text-[#F5A623] group-hover:text-[#F5A623]" />
              </div>
            </Link>
          ) : null}

          {/* Breadcrumbs (sm+) */}
          {breadcrumbs && breadcrumbs.length > 0 && (
            <div className="hidden sm:flex items-center gap-1.5 text-[10px] font-black uppercase tracking-widest text-neutral-600 shrink-0">
              {breadcrumbs.map((bc, i) => (
                <span key={i} className="flex items-center gap-1.5">
                  {bc.href ? (
                    <Link href={bc.href} className="hover:text-neutral-400 transition-colors">{bc.label}</Link>
                  ) : (
                    <span>{bc.label}</span>
                  )}
                  {i < breadcrumbs.length - 1 && <span className="text-neutral-700">/</span>}
                </span>
              ))}
              <span className="text-neutral-700">/</span>
            </div>
          )}

          {/* Title + Subtitle */}
          <div className="flex items-center gap-2 min-w-0">
            {icon && <div className="shrink-0 text-[#F5A623]">{icon}</div>}
            <div className="min-w-0">
              <h1 className="font-black text-white text-sm sm:text-base uppercase tracking-tight leading-none truncate">
                {title}
              </h1>
              {subtitle && (
                <p className="text-[10px] text-neutral-500 font-semibold hidden sm:block mt-0.5 truncate">
                  {subtitle}
                </p>
              )}
            </div>
          </div>
        </div>

        {/* ── RIGHT: Actions + Status + Role + User ── */}
        <div className="flex items-center gap-2 sm:gap-3 shrink-0">

          {/* Page-level actions slot */}
          {actions && <div className="flex items-center gap-2">{actions}</div>}

          {/* Online status pill (only when explicitly provided) */}
          {isOnline !== null && (
            <div className="hidden sm:flex items-center gap-1.5 bg-neutral-900 border border-neutral-800 px-2.5 py-1.5 rounded-full text-[10px] font-mono">
              {isOnline ? (
                <>
                  <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />
                  <span className="text-emerald-400">Live</span>
                </>
              ) : (
                <>
                  <span className="w-1.5 h-1.5 rounded-full bg-red-500" />
                  <span className="text-red-400">Offline</span>
                </>
              )}
            </div>
          )}

          {/* Role badge */}
          {role && (
            <span className={`hidden sm:inline-flex text-[9px] font-black uppercase tracking-wider px-2.5 py-1 rounded-full border ${ROLE_COLOR[role] || 'bg-neutral-900 text-neutral-400 border-neutral-800'}`}>
              {ROLE_SHORT[role] || role}
            </span>
          )}

          {/* User initial (mobile) */}
          {name && (
            <div className="sm:hidden w-8 h-8 bg-[#F5A623]/20 border border-[#F5A623]/40 rounded-full flex items-center justify-center text-[#F5A623] font-black text-sm">
              {name.charAt(0).toUpperCase()}
            </div>
          )}

          {/* User name + Sign out (desktop) */}
          <div className="hidden sm:flex items-center gap-2 pl-2 border-l border-neutral-800">
            {name && (
              <span className="text-[11px] text-neutral-400 font-semibold max-w-[80px] truncate">
                {name.split(' ')[0]}
              </span>
            )}
            <button
              onClick={() => void signOut({ callbackUrl: '/login' })}
              title="Sign out"
              className="flex items-center gap-1.5 text-neutral-500 hover:text-red-400 text-xs font-bold uppercase tracking-wide transition-colors"
            >
              <LogOut className="w-3.5 h-3.5" />
              <span className="hidden lg:block">Sign out</span>
            </button>
          </div>

          {/* Sign out icon only (mobile) */}
          <button
            onClick={() => void signOut({ callbackUrl: '/login' })}
            className="sm:hidden p-2 text-neutral-600 hover:text-red-400 transition-colors"
            title="Sign out"
          >
            <LogOut className="w-4 h-4" />
          </button>
        </div>
      </div>

      {/* Thin gold progress bar accent */}
      <div className="h-[2px] bg-gradient-to-r from-[#F5A623]/0 via-[#F5A623]/40 to-[#F5A623]/0" />
    </header>
  );
}

'use client';

import React from 'react';
import { cn } from '@/lib/utils';
import { cva, type VariantProps } from 'class-variance-authority';
import { motion } from 'framer-motion';

const buttonVariants = cva('btn', {
  variants: {
    variant: {
      primary: 'btn-primary',
      dark: 'btn-dark',
      ghost: 'btn-ghost',
      danger: 'btn-danger',
      green: 'btn-green',
    },
    size: {
      sm: 'btn-sm',
      md: 'min-h-[56px] sm:min-h-[48px]',
      lg: 'btn-lg',
      icon: 'btn-icon',
    },
  },
  defaultVariants: {
    variant: 'primary',
    size: 'md',
  },
});

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  loading?: boolean;
  icon?: React.ReactNode;
}

export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, loading, children, icon, disabled, onClick, ...props }, ref) => {
    return (
      <motion.button
        ref={ref}
        className={cn(buttonVariants({ variant, size }), className)}
        disabled={disabled || loading}
        whileHover={{ x: -2, y: -2 }}
        whileTap={{ x: 2, y: 2, boxShadow: 'none' }}
        transition={{ duration: 0.1 }}
        onClick={(e) => {
          if (typeof window !== 'undefined' && window.navigator && window.navigator.vibrate) {
            window.navigator.vibrate(10); // Light haptic tap
          }
          if (onClick) {
            onClick(e);
          }
        }}
        {...(props as any)}
      >
        {loading ? (
          <span className="inline-block w-4 h-4 border-2 border-current border-t-transparent rounded-full animate-spin" />
        ) : icon}
        {children}
      </motion.button>
    );
  }
);
Button.displayName = 'Button';
